function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeInOutCubic(x) {
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawLeaf(x, y, angle, length, widthFactor, openAmt, colorLeft, colorRight, borderColor, borderW) {
    if (openAmt <= 0.01 || length <= 0.5) return;
    const len = length * openAmt;
    const halfW = len * widthFactor;

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(len * 0.28, -halfW, len * 0.76, -halfW * 0.72, len, 0);
    ctx.bezierCurveTo(len * 0.76, halfW * 0.72, len * 0.28, halfW, 0, 0);
    ctx.closePath();
    ctx.lineWidth = borderW;
    ctx.strokeStyle = borderColor;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(len * 0.28, -halfW, len * 0.76, -halfW * 0.72, len, 0);
    ctx.lineTo(0, 0);
    ctx.closePath();
    ctx.fillStyle = colorLeft;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(len, 0);
    ctx.bezierCurveTo(len * 0.76, halfW * 0.72, len * 0.28, halfW, 0, 0);
    ctx.closePath();
    ctx.fillStyle = colorRight;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(len * 0.14, 0);
    ctx.lineTo(len * 0.78, 0);
    ctx.lineWidth = Math.max(1, minSide * 0.0022);
    ctx.strokeStyle = "#ECFDF5";
    ctx.stroke();

    ctx.restore();
  }

  function evalCubic(p0, p1, p2, p3, u) {
    const o = 1 - u;
    return (
      o * o * o * p0 +
      3 * o * o * u * p1 +
      3 * o * u * u * p2 +
      u * u * u * p3
    );
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#070D1F");
  bgGrad.addColorStop(0.52, "#0C1736");
  bgGrad.addColorStop(1, "#12234D");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let dockOffset = 0; // 0 = rest unplugged, -0.2 = slight anticipation, 1 = cleanly docked
  let cableFlow = 0;
  let leafBloom = 0;
  let chargeLevel = 0.16;
  let fullPing = 0;

  if (currentScene === 0) {
    // Scene 0: Plug smoothly pulls back slightly in anticipation, then glides forward and locks into socket
    if (sceneProgress < 0.24) {
      dockOffset = -0.18 * smoothRange(sceneProgress, 0.0, 0.24);
    } else {
      dockOffset = lerp(-0.18, 1.0, easeInOutCubic(clamp01((sceneProgress - 0.24) / 0.48)));
    }
    cableFlow = smoothRange(sceneProgress, 0.70, 0.98);
    leafBloom = 0;
    chargeLevel = 0.16;
    fullPing = 0;
  } else if (currentScene === 1) {
    // Scene 1: Plug stays locked; energy pulses travel cable; eco-leaves bloom; circular charge climbs to 100%
    dockOffset = 1.0;
    cableFlow = 1.0;
    leafBloom = smoothRange(sceneProgress, 0.08, 0.62);
    chargeLevel = 0.16 + 0.84 * smoothRange(sceneProgress, 0.14, 0.94);
    fullPing = smoothRange(sceneProgress, 0.82, 1.0);
  } else {
    // Scene 2: Full-charge confirmation arcs on right side of socket; leaves fold; smooth unplug reset
    dockOffset = 1.0 - smoothRange(sceneProgress, 0.46, 0.94);
    cableFlow = 1.0 - smoothRange(sceneProgress, 0.24, 0.56);
    leafBloom = 1.0 - smoothRange(sceneProgress, 0.20, 0.54);
    chargeLevel = 1.0 - 0.84 * smoothRange(sceneProgress, 0.48, 0.95);
    fullPing = 1.0 - smoothRange(sceneProgress, 0.34, 0.62);
  }

  // 3. Layout Coordinates (Horizontal balance around cx, cy)
  const cx = width * 0.5;
  const cy = height * 0.50;

  const sockX = cx + minSide * 0.155;
  const sockR = minSide * 0.132;
  const portRightX = sockX - sockR + minSide * 0.008;
  const portW = minSide * 0.044;
  const portLeftX = portRightX - portW; // ~ cx - 0.013 * minSide
  const portH = minSide * 0.106;

  // Moving Plug Front Face X:
  // Rest (dockOffset = 0): cx - 0.125 * minSide (huge 0.112 * minSide clear gap to portLeftX!)
  // Docked (dockOffset = 1): portLeftX + minSide * 0.002 (seats flush against receptacle!)
  const restFrontX = cx - minSide * 0.125;
  const dockedFrontX = portLeftX + minSide * 0.002;
  const plugFrontX = lerp(restFrontX, dockedFrontX, dockOffset);

  const plugW = minSide * 0.138;
  const plugH = minSide * 0.094;
  const plugBackX = plugFrontX - plugW;
  const prongLen = minSide * 0.036;

  // 4. Flexible Bezier Power Cable (Left Anchor -> Plug Strain-Relief Boot)
  const cabX0 = cx - minSide * 0.420;
  const cabY0 = cy + minSide * 0.115;
  const cabX3 = plugBackX - minSide * 0.010;
  const cabY3 = cy;
  const cabX1 = cabX0 + minSide * 0.12;
  const cabY1 = cabY0;
  const cabX2 = cabX3 - minSide * 0.11;
  const cabY2 = cabY3;

  // Cable outer jacket
  ctx.beginPath();
  ctx.moveTo(cabX0, cabY0);
  ctx.bezierCurveTo(cabX1, cabY1, cabX2, cabY2, cabX3, cabY3);
  ctx.lineWidth = minSide * 0.022;
  ctx.strokeStyle = "#334155";
  ctx.stroke();

  // Cable inner groove
  ctx.beginPath();
  ctx.moveTo(cabX0, cabY0);
  ctx.bezierCurveTo(cabX1, cabY1, cabX2, cabY2, cabX3, cabY3);
  ctx.lineWidth = minSide * 0.008;
  ctx.strokeStyle = "#1E293B";
  ctx.stroke();

  // Traveling Energy Pulses along exact Bezier cable
  if (cableFlow > 0.02) {
    for (let k = 0; k < 3; k++) {
      const pNorm = (cycleNorm * 5 + k / 3) % 1;
      const alpha = Math.sin(Math.PI * pNorm) * cableFlow;
      if (alpha > 0.04) {
        const px = evalCubic(cabX0, cabX1, cabX2, cabX3, pNorm);
        const py = evalCubic(cabY0, cabY1, cabY2, cabY3, pNorm);
        ctx.beginPath();
        ctx.arc(px, py, minSide * 0.0062, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(163, 255, 18, " + alpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // Cable Anchor Terminal Cap at left end (clean visual termination)
  ctx.beginPath();
  ctx.arc(cabX0, cabY0, minSide * 0.016, 0, Math.PI * 2);
  ctx.fillStyle = "#1E293B";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.004);
  ctx.strokeStyle = "#64748B";
  ctx.stroke();

  // 5. Metallic Prongs (Drawn BEFORE socket receptacle so they slide cleanly into slot when docked!)
  const prongThick = minSide * 0.013;
  const prongOffset = minSide * 0.022;
  for (let side = -1; side <= 1; side += 2) {
    roundedRectPath(
      plugFrontX - minSide * 0.006,
      cy + side * prongOffset - prongThick * 0.5,
      prongLen + minSide * 0.006,
      prongThick,
      prongThick * 0.45
    );
    ctx.fillStyle = "#CBD5E1";
    ctx.fill();
  }

  // 6. Full-Charge Confirmation Arcs on Right Perimeter of Socket ([-105°, +105°] ONLY — zero contact with plug!)
  if (fullPing > 0.01) {
    for (let r = 0; r < 2; r++) {
      const rProg = (cycleNorm * 4 + r * 0.5) % 1;
      const rAlpha = Math.sin(Math.PI * rProg) * fullPing * 0.85;
      if (rAlpha > 0.03) {
        const arcR = sockR + minSide * (0.022 + 0.036 * rProg);
        ctx.beginPath();
        ctx.arc(sockX, cy, arcR, -Math.PI * 0.42, Math.PI * 0.42);
        ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
        ctx.strokeStyle = "rgba(163, 255, 18, " + rAlpha.toFixed(3) + ")";
        ctx.stroke();
      }
    }
  }

  // 7. Right Circular Charging Socket & Docking Port Collar
  // Receptacle Collar seated cleanly on left edge of socket
  roundedRectPath(portLeftX, cy - portH * 0.5, portW, portH, minSide * 0.014);
  ctx.fillStyle = "#1E293B";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0052;
  ctx.strokeStyle = "#94A3B8";
  ctx.stroke();

  // Socket main circular base
  ctx.beginPath();
  ctx.arc(sockX, cy, sockR, 0, Math.PI * 2);
  ctx.fillStyle = "#0B1633";
  ctx.fill();
  ctx.lineWidth = minSide * 0.006;
  ctx.strokeStyle = "#334155";
  ctx.stroke();

  // Progress Ring Track
  const ringR = sockR - minSide * 0.018;
  ctx.beginPath();
  ctx.arc(sockX, cy, ringR, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.013;
  ctx.strokeStyle = "#162A5A";
  ctx.stroke();

  // Active Charge Arc (Sky Blue -> Neon Lime)
  const chargeColor = lerpColor([56, 189, 248], [163, 255, 18], clamp01((chargeLevel - 0.16) / 0.84));
  ctx.beginPath();
  ctx.arc(sockX, cy, ringR, -Math.PI * 0.5, -Math.PI * 0.5 + Math.PI * 2 * chargeLevel);
  ctx.lineWidth = minSide * 0.013;
  ctx.strokeStyle = chargeColor;
  ctx.stroke();

  // Center Lightning Bolt Emblem inside Socket
  const boltScale = minSide * 0.056;
  ctx.save();
  ctx.translate(sockX, cy);
  ctx.beginPath();
  ctx.moveTo(boltScale * 0.14, -boltScale * 0.88);
  ctx.lineTo(-boltScale * 0.44, boltScale * 0.06);
  ctx.lineTo(-boltScale * 0.02, boltScale * 0.06);
  ctx.lineTo(-boltScale * 0.14, boltScale * 0.88);
  ctx.lineTo(boltScale * 0.44, -boltScale * 0.06);
  ctx.lineTo(boltScale * 0.02, -boltScale * 0.06);
  ctx.closePath();
  ctx.fillStyle = chargeLevel > 0.88 ? "#A3FF12" : "#38BDF8";
  ctx.fill();
  ctx.restore();

  // 8. Botanical Eco-Leaves Sprouting Cleanly Above & Below Plug Body (Strictly clear of cable and socket)
  const leafSway = Math.sin(cycleNorm * Math.PI * 2 * 3) * 0.04;
  const leafBaseX = plugFrontX - plugW * 0.54;
  drawLeaf(
    leafBaseX,
    cy - plugH * 0.5 - minSide * 0.004,
    -Math.PI * 0.68 + leafSway,
    minSide * 0.056,
    0.36,
    leafBloom,
    "#D9F99D",
    "#A3FF12",
    "#070D1F",
    minSide * 0.0065
  );
  drawLeaf(
    leafBaseX,
    cy + plugH * 0.5 + minSide * 0.004,
    Math.PI * 0.68 - leafSway,
    minSide * 0.056,
    0.36,
    leafBloom,
    "#A3FF12",
    "#D9F99D",
    "#070D1F",
    minSide * 0.0065
  );

  // 9. EV Charger Plug Handle & Strain Relief Boot
  // Strain-relief neck collar at back of plug
  const bootW = minSide * 0.026;
  const bootH = minSide * 0.046;
  roundedRectPath(plugBackX - bootW + minSide * 0.004, cy - bootH * 0.5, bootW, bootH, minSide * 0.010);
  ctx.fillStyle = "#475569";
  ctx.fill();

  // Main Plug Shell (Pure White upper + Slate shaded lower half)
  const plugR = minSide * 0.022;
  roundedRectPath(plugBackX, cy - plugH * 0.5, plugW, plugH, plugR);
  ctx.fillStyle = "#F8FAFC";
  ctx.fill();

  ctx.save();
  roundedRectPath(plugBackX, cy - plugH * 0.5, plugW, plugH, plugR);
  ctx.clip();
  ctx.fillStyle = "#CBD5E1";
  ctx.fillRect(plugBackX, cy + plugH * 0.14, plugW, plugH * 0.40);
  ctx.restore();

  roundedRectPath(plugBackX, cy - plugH * 0.5, plugW, plugH, plugR);
  ctx.lineWidth = minSide * 0.0052;
  ctx.strokeStyle = "#E2E8F0";
  ctx.stroke();

  // Electric Violet & Neon Lime Indicator Strip on Plug Body
  const stripW = plugW * 0.46;
  const stripH = minSide * 0.018;
  const stripX = plugBackX + plugW * 0.27;
  const stripY = cy - stripH * 0.5;
  roundedRectPath(stripX, stripY, stripW, stripH, stripH * 0.5);
  ctx.fillStyle = "#1E293B";
  ctx.fill();

  const ledFillW = stripW * lerp(0.35, 1.0, clamp01(dockOffset));
  roundedRectPath(stripX, stripY, ledFillW, stripH, stripH * 0.5);
  ctx.fillStyle = cableFlow > 0.2 ? "#A3FF12" : "#8B5CF6";
  ctx.fill();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  // Unified sleek silhouette: wide curved intake funnel -> neck -> reaction chamber -> rounded vault base
  function traceReactorPath(cx, funnelTopY, funnelHalfW, neckY, neckHalfW, bodyHalfW, bodyTopY, vaultBotY, cornerR) {
    ctx.beginPath();
    ctx.moveTo(cx - funnelHalfW, funnelTopY);
    ctx.lineTo(cx + funnelHalfW, funnelTopY);
    // Right funnel curve inward to neck
    ctx.bezierCurveTo(
      cx + funnelHalfW * 0.86,
      lerp(funnelTopY, neckY, 0.55),
      cx + neckHalfW,
      lerp(funnelTopY, neckY, 0.72),
      cx + neckHalfW,
      neckY
    );
    // Step smoothly outward to main reactor cylinder
    ctx.quadraticCurveTo(cx + bodyHalfW, neckY, cx + bodyHalfW, bodyTopY);
    ctx.lineTo(cx + bodyHalfW, vaultBotY - cornerR);
    ctx.quadraticCurveTo(cx + bodyHalfW, vaultBotY, cx + bodyHalfW - cornerR, vaultBotY);
    ctx.lineTo(cx - bodyHalfW + cornerR, vaultBotY);
    ctx.quadraticCurveTo(cx - bodyHalfW, vaultBotY, cx - bodyHalfW, vaultBotY - cornerR);
    ctx.lineTo(cx - bodyHalfW, bodyTopY);
    ctx.quadraticCurveTo(cx - bodyHalfW, neckY, cx - neckHalfW, neckY);
    // Left funnel curve outward to top rim
    ctx.bezierCurveTo(
      cx - neckHalfW,
      lerp(funnelTopY, neckY, 0.72),
      cx - funnelHalfW * 0.86,
      lerp(funnelTopY, neckY, 0.55),
      cx - funnelHalfW,
      funnelTopY
    );
    ctx.closePath();
  }

  function drawHexCrystal(hx, hy, radius, scale, scanY) {
    if (scale <= 0.02) return;
    const r = radius * scale;
    const w = r * 0.76;
    const h = r;

    ctx.save();
    ctx.translate(hx, hy);

    // 2D flat-vector pointed hex prism (left half lighter, right half darker)
    ctx.beginPath();
    ctx.moveTo(0, -h);
    ctx.lineTo(-w, -h * 0.42);
    ctx.lineTo(-w, h * 0.42);
    ctx.lineTo(0, h);
    ctx.lineTo(0, -h);
    ctx.closePath();
    ctx.fillStyle = "#A855F7";
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(0, -h);
    ctx.lineTo(0, h);
    ctx.lineTo(w, h * 0.42);
    ctx.lineTo(w, -h * 0.42);
    ctx.closePath();
    ctx.fillStyle = "#6D28D9";
    ctx.fill();

    // Inner teal mineral core facet
    ctx.beginPath();
    ctx.moveTo(0, -h * 0.58);
    ctx.lineTo(w * 0.48, -h * 0.22);
    ctx.lineTo(w * 0.48, h * 0.22);
    ctx.lineTo(0, h * 0.58);
    ctx.lineTo(-w * 0.48, h * 0.22);
    ctx.lineTo(-w * 0.48, -h * 0.22);
    ctx.closePath();
    ctx.fillStyle = "#2DD4BF";
    ctx.fill();

    // Specular scan highlight clipped inside crystal
    if (scanY > -1.2 && scanY < 1.2) {
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(0, -h);
      ctx.lineTo(w, -h * 0.42);
      ctx.lineTo(w, h * 0.42);
      ctx.lineTo(0, h);
      ctx.lineTo(-w, h * 0.42);
      ctx.lineTo(-w, -h * 0.42);
      ctx.closePath();
      ctx.clip();

      ctx.fillStyle = "rgba(255, 255, 255, 0.38)";
      ctx.fillRect(-w * 1.2, scanY * h - h * 0.14, w * 2.4, h * 0.28);
      ctx.restore();
    }

    // Crisp crystal border
    ctx.beginPath();
    ctx.moveTo(0, -h);
    ctx.lineTo(w, -h * 0.42);
    ctx.lineTo(w, h * 0.42);
    ctx.lineTo(0, h);
    ctx.lineTo(-w, h * 0.42);
    ctx.lineTo(-w, -h * 0.42);
    ctx.closePath();
    ctx.lineWidth = Math.max(1.5, minSide * 0.0034);
    ctx.strokeStyle = "#E9D5FF";
    ctx.stroke();

    ctx.restore();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#101018");
  bgGrad.addColorStop(0.52, "#191827");
  bgGrad.addColorStop(1, "#222036");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography & Loop-Locked Fan Kinematics
  // Analytic fan rotation: 3 base + 6*0.5 boost = 6 EXACT revolutions over 20s!
  const revIntegral = 3 * cycleNorm + 6 * (0.5 * cycleNorm - Math.sin(Math.PI * 2 * cycleNorm) / (4 * Math.PI));
  const fanAngle = revIntegral * Math.PI * 2;

  let intakeFlow = 0.22;
  let catalystPower = 0.25;
  let oxygenOut = 0;
  let crystalGrowth = 0.28;
  let scanPos = -1.5;

  if (currentScene === 0) {
    // Scene 0: Carbon emission bubbles sucked into funnel intake; catalyst powers up
    intakeFlow = 0.22 + 0.78 * smoothRange(sceneProgress, 0.06, 0.76);
    catalystPower = 0.25 + 0.70 * smoothRange(sceneProgress, 0.20, 0.96);
    oxygenOut = 0;
    crystalGrowth = 0.28;
    scanPos = -1.5;
  } else if (currentScene === 1) {
    // Scene 1: Active catalytic conversion -> pure oxygen vents sideways, mineral carbon crystal grows
    intakeFlow = 1.0 - 0.70 * smoothRange(sceneProgress, 0.65, 1.0);
    catalystPower = 0.95 + 0.05 * Math.sin(Math.PI * sceneProgress);
    oxygenOut = smoothRange(sceneProgress, 0.12, 0.56);
    crystalGrowth = 0.28 + 0.72 * smoothRange(sceneProgress, 0.24, 0.94);
    scanPos = -1.5;
  } else {
    // Scene 2: Mineral crystal locked & scanned; oxygen completes exhaust; smooth reset to start
    intakeFlow = 0.30 - 0.08 * smoothRange(sceneProgress, 0.20, 0.90);
    catalystPower = 0.95 - 0.70 * smoothRange(sceneProgress, 0.45, 0.95);
    oxygenOut = 1.0 - smoothRange(sceneProgress, 0.28, 0.76);
    crystalGrowth = 1.0 - 0.72 * smoothRange(sceneProgress, 0.52, 0.95);
    if (sceneProgress < 0.52) {
      scanPos = lerp(-1.5, 1.5, clamp01(sceneProgress / 0.48));
    } else {
      scanPos = -1.5;
    }
  }

  // 3. Layout Coordinates (Balanced 16:9, strict separation)
  const cx = width * 0.5;
  const funnelTopY = height * 0.285;
  const funnelHalfW = minSide * 0.145;
  const neckY = height * 0.378;
  const neckHalfW = minSide * 0.056;
  const bodyHalfW = minSide * 0.124;
  const bodyTopY = height * 0.432;
  const floorY = height * 0.660;
  const vaultBotY = height * 0.835;
  const cornerR = minSide * 0.032;

  // 4. Carbon Emission Bubbles Entering Top Funnel Corridor (Strictly above neck, zero wall collisions)
  if (intakeFlow > 0.03) {
    const skyTopY = height * 0.140;
    const skyBotY = funnelTopY + minSide * 0.025;
    const lanes = [
      { xStart: -0.085, xEnd: -0.024, r: 0.015, phase: 0.0 },
      { xStart: 0.0, xEnd: 0.0, r: 0.018, phase: 0.33 },
      { xStart: 0.085, xEnd: 0.024, r: 0.015, phase: 0.66 },
    ];

    for (let i = 0; i < lanes.length; i++) {
      const b = lanes[i];
      const pNorm = (cycleNorm * 4 + b.phase) % 1;
      const alpha = Math.sin(Math.PI * pNorm) * intakeFlow * 0.88;
      if (alpha > 0.04) {
        const bx = cx + lerp(b.xStart, b.xEnd, pNorm * pNorm) * minSide;
        const by = lerp(skyTopY, skyBotY, pNorm);
        const br = minSide * b.r * (1 - 0.35 * pNorm);
        ctx.beginPath();
        ctx.arc(bx, by, br, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(156, 163, 175, " + alpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // 5. Side Oxygen Exhaust Ports & Outflowing Pure Teal Orbs (Left & Right Flanks)
  const ventY = height * 0.535;
  const ventW = minSide * 0.030;
  const ventH = minSide * 0.044;

  for (let side = -1; side <= 1; side += 2) {
    const vx = side === 1 ? cx + bodyHalfW - minSide * 0.004 : cx - bodyHalfW - ventW + minSide * 0.004;
    roundedRectPath(vx, ventY - ventH * 0.5, ventW, ventH, minSide * 0.008);
    ctx.fillStyle = "#1E293B";
    ctx.fill();
    ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
    ctx.strokeStyle = "#E5E7EB";
    ctx.stroke();

    // Pure Oxygen Teal Orbs gliding smoothly outward & upward from exhaust port
    if (oxygenOut > 0.02) {
      const exStartX = cx + side * (bodyHalfW + ventW + minSide * 0.016);
      const exEndX = cx + side * (bodyHalfW + ventW + minSide * 0.135);
      for (let k = 0; k < 2; k++) {
        const kProg = (cycleNorm * 4 + k * 0.5 + (side === 1 ? 0 : 0.25)) % 1;
        const kAlpha = Math.sin(Math.PI * kProg) * oxygenOut * 0.92;
        if (kAlpha > 0.04) {
          const ox = lerp(exStartX, exEndX, kProg);
          const oy = ventY - minSide * 0.045 * Math.pow(kProg, 1.3);
          const or = minSide * (0.011 - 0.003 * kProg);
          ctx.beginPath();
          ctx.arc(ox, oy, or, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(45, 212, 191, " + kAlpha.toFixed(3) + ")";
          ctx.fill();
        }
      }
    }
  }

  // 6. Reactor Main Housing Interior (Clipped)
  traceReactorPath(cx, funnelTopY, funnelHalfW, neckY, neckHalfW, bodyHalfW, bodyTopY, vaultBotY, cornerR);
  ctx.fillStyle = "#161524";
  ctx.fill();

  ctx.save();
  traceReactorPath(cx, funnelTopY, funnelHalfW, neckY, neckHalfW, bodyHalfW, bodyTopY, vaultBotY, cornerR);
  ctx.clip();

  // Subtle flat-vector right-side shadow band
  ctx.fillStyle = "#100F1B";
  ctx.fillRect(cx + bodyHalfW * 0.38, funnelTopY, funnelHalfW, vaultBotY - funnelTopY);

  // Funnel intake recessed throat shading
  ctx.fillStyle = "rgba(156, 163, 175, 0.08)";
  ctx.fillRect(cx - funnelHalfW, funnelTopY, funnelHalfW * 2, neckY - funnelTopY);

  // Horizontal divider plates (Neck Plate & Catalytic Floor Sieve)
  ctx.fillStyle = "#2E2B45";
  ctx.fillRect(cx - bodyHalfW, neckY - minSide * 0.008, bodyHalfW * 2, minSide * 0.016);
  ctx.fillRect(cx - bodyHalfW, floorY - minSide * 0.008, bodyHalfW * 2, minSide * 0.016);

  // --- REACTION CHAMBER CATALYTIC WAVE & SEPARATION PARTICLES ---
  const wavePhase = cycleNorm * Math.PI * 2 * 6;
  const waveY = (bodyTopY + floorY) * 0.5;
  const waveAmp = minSide * 0.009 * catalystPower;

  // Dual crisp catalytic plasma waves spanning chamber width cleanly
  for (let w = 0; w < 2; w++) {
    ctx.beginPath();
    const steps = 28;
    for (let s = 0; s <= steps; s++) {
      const u = s / steps;
      const wx = cx - bodyHalfW + u * bodyHalfW * 2;
      const wy =
        waveY +
        (w === 0 ? -minSide * 0.012 : minSide * 0.012) +
        Math.sin(u * Math.PI * 2.5 + wavePhase + w * 1.4) * waveAmp;
      if (s === 0) ctx.moveTo(wx, wy);
      else ctx.lineTo(wx, wy);
    }
    ctx.lineWidth = Math.max(1.8, minSide * 0.0044);
    ctx.strokeStyle = w === 0 ? "#A855F7" : "#2DD4BF";
    ctx.globalAlpha = 0.45 + 0.55 * catalystPower;
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  // Internal carbon precipitate grains falling cleanly from catalyst down to floor sieve
  const precipTop = waveY + minSide * 0.025;
  const precipBot = floorY - minSide * 0.018;
  const pCols = [-0.045, 0.0, 0.045];
  for (let i = 0; i < pCols.length; i++) {
    const pNorm = (cycleNorm * 4 + i * 0.333) % 1;
    const py = lerp(precipTop, precipBot, pNorm);
    const px = cx + pCols[i] * minSide;
    const pAlpha = Math.sin(Math.PI * pNorm) * catalystPower * 0.85;
    if (pAlpha > 0.03) {
      ctx.beginPath();
      ctx.arc(px, py, minSide * 0.0045, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(192, 132, 252, " + pAlpha.toFixed(3) + ")";
      ctx.fill();
    }
  }

  // --- BOTTOM MINERALIZATION VAULT: HEX CARBON CRYSTAL CLUSTER ---
  const vaultCy = (floorY + vaultBotY) * 0.5 + minSide * 0.004;
  drawHexCrystal(cx - minSide * 0.048, vaultCy + minSide * 0.008, minSide * 0.026, crystalGrowth, scanPos);
  drawHexCrystal(cx + minSide * 0.048, vaultCy + minSide * 0.008, minSide * 0.026, crystalGrowth, scanPos);
  drawHexCrystal(cx, vaultCy - minSide * 0.002, minSide * 0.042, crystalGrowth, scanPos);

  ctx.restore();

  // Outer Chrome Reactor Border
  traceReactorPath(cx, funnelTopY, funnelHalfW, neckY, neckHalfW, bodyHalfW, bodyTopY, vaultBotY, cornerR);
  ctx.lineWidth = minSide * 0.0072;
  ctx.strokeStyle = "#E5E7EB";
  ctx.stroke();

  // Clean Top Funnel Lip Collar Ring
  const lipW = funnelHalfW * 2.08;
  const lipH = minSide * 0.020;
  roundedRectPath(cx - lipW * 0.5, funnelTopY - lipH * 0.5, lipW, lipH, lipH * 0.5);
  ctx.fillStyle = "#2E2B45";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.0045);
  ctx.strokeStyle = "#E5E7EB";
  ctx.stroke();

  // 7. Neck Rotary Turbine Porthole (Cleanly centered on neck junction)
  const fanR = minSide * 0.028;
  ctx.beginPath();
  ctx.arc(cx, neckY, fanR, 0, Math.PI * 2);
  ctx.fillStyle = "#100F1B";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.004);
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  ctx.save();
  ctx.translate(cx, neckY);
  ctx.rotate(fanAngle);
  for (let b = 0; b < 4; b++) {
    ctx.rotate(Math.PI * 0.5);
    roundedRectPath(-minSide * 0.0035, -fanR * 0.72, minSide * 0.007, fanR * 0.66, minSide * 0.0035);
    ctx.fillStyle = "#94A3B8";
    ctx.fill();
  }
  ctx.beginPath();
  ctx.arc(0, 0, minSide * 0.007, 0, Math.PI * 2);
  ctx.fillStyle = "#2DD4BF";
  ctx.fill();
  ctx.restore();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#030E1A");
  bgGrad.addColorStop(0.52, "#061B30");
  bgGrad.addColorStop(1, "#092A47");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let sonarActive = 0.25;
  let debrisVis = 0;
  let debrisPull = 0;
  let intakeOpen = 0;
  let purityLevel = 0.25;
  let cleanState = 0;
  let skyPing = 0;

  if (currentScene === 0) {
    // Scene 0: Sonar sweeps deep underwater, geometric debris particles drift in submerged side lanes
    sonarActive = 0.25 + 0.75 * smoothRange(sceneProgress, 0.05, 0.55);
    debrisVis = smoothRange(sceneProgress, 0.12, 0.52);
    debrisPull = 0;
    intakeOpen = 0;
    purityLevel = 0.25;
    cleanState = 0;
    skyPing = 0;
  } else if (currentScene === 1) {
    // Scene 1: Underwater intake valves open, debris particles smoothly glide inward into collector, purity climbs
    sonarActive = 1.0 - 0.55 * smoothRange(sceneProgress, 0.70, 1.0);
    debrisPull = smoothRange(sceneProgress, 0.18, 0.86);
    debrisVis = 1.0 - smoothRange(sceneProgress, 0.74, 0.92);
    intakeOpen = Math.sin(Math.PI * clamp01((sceneProgress - 0.06) / 0.90));
    purityLevel = 0.25 + 0.75 * smoothRange(sceneProgress, 0.22, 0.95);
    cleanState = smoothRange(sceneProgress, 0.72, 1.0);
    skyPing = smoothRange(sceneProgress, 0.78, 1.0) * 0.35;
  } else {
    // Scene 2: Emerald beacon clean lock with sky confirmation arcs, then smooth seamless reset
    sonarActive = 0.45 - 0.20 * smoothRange(sceneProgress, 0.35, 0.90);
    debrisVis = 0;
    debrisPull = 0;
    intakeOpen = 0;
    purityLevel = 1.0 - 0.75 * smoothRange(sceneProgress, 0.56, 0.96);
    cleanState = 1.0 - smoothRange(sceneProgress, 0.58, 0.94);
    skyPing = 0.35 + 0.65 * Math.sin(Math.PI * clamp01(sceneProgress / 0.62));
    if (sceneProgress >= 0.62) {
      skyPing = 0.35 * (1 - smoothRange(sceneProgress, 0.62, 0.90));
    }
  }

  // Exact integer harmonics across 20s for seamless loop
  const wavePhase = cycleNorm * Math.PI * 2 * 5;
  const backPhase = cycleNorm * Math.PI * 2 * 4;

  // 3. Layout Coordinates (Porthole Ocean Emblem + Flanking Telemetry Gauge Arcs)
  const cx = width * 0.5;
  const cy = height * 0.50;
  const portholeR = minSide * 0.255;

  // Flanking Outer Marine Purity Gauge Arcs (Strictly outside porthole rim + 0.038 * minSide gap)
  const gaugeR = portholeR + minSide * 0.042;
  const gaugeSpan = 0.46;
  const gaugeColor = lerpColor([255, 107, 53], [52, 211, 153], cleanState);

  for (let side = -1; side <= 1; side += 2) {
    const midA = side === 1 ? 0 : Math.PI;
    const a0 = midA - gaugeSpan;
    const a1 = midA + gaugeSpan;

    ctx.beginPath();
    ctx.arc(cx, cy, gaugeR, a0, a1);
    ctx.lineWidth = minSide * 0.011;
    ctx.strokeStyle = "#0E2D4D";
    ctx.stroke();

    const fillSpan = gaugeSpan * 2 * purityLevel;
    const actStart = side === 1 ? a1 - fillSpan : a0;
    const actEnd = side === 1 ? a1 : a0 + fillSpan;
    ctx.beginPath();
    ctx.arc(cx, cy, gaugeR, actStart, actEnd);
    ctx.lineWidth = minSide * 0.011;
    ctx.strokeStyle = gaugeColor;
    ctx.stroke();
  }

  // 4. Main Circular Porthole Interior (Clipped)
  ctx.beginPath();
  ctx.arc(cx, cy, portholeR, 0, Math.PI * 2);
  ctx.fillStyle = "#041224";
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, portholeR - minSide * 0.004, 0, Math.PI * 2);
  ctx.clip();

  // Night ocean sky gradient inside upper porthole
  const skyGrad = ctx.createLinearGradient(cx, cy - portholeR, cx, cy + minSide * 0.05);
  skyGrad.addColorStop(0, "#05162E");
  skyGrad.addColorStop(1, "#0B294E");
  ctx.fillStyle = skyGrad;
  ctx.fillRect(cx - portholeR, cy - portholeR, portholeR * 2, portholeR * 2);

  // Wave surface math at center (buoy sits physically coupled to front wave height & slope!)
  const waterBaseY = cy + minSide * 0.026;
  const waveAmp = minSide * 0.014;
  const waveFreq = (Math.PI * 1.45) / portholeR;

  function frontWaveY(x) {
    return waterBaseY + Math.sin((x - cx) * waveFreq + wavePhase) * waveAmp;
  }

  const buoyY = frontWaveY(cx);
  const waveSlope = waveFreq * waveAmp * Math.cos(wavePhase);
  const buoyTilt = Math.atan(waveSlope) * 0.72;

  // Back Ocean Wave (Deep Ultramarine, opaque behind buoy)
  const wSteps = 44;
  ctx.beginPath();
  ctx.moveTo(cx - portholeR, cy + portholeR);
  for (let s = 0; s <= wSteps; s++) {
    const u = s / wSteps;
    const wx = cx - portholeR + u * portholeR * 2;
    const wy = waterBaseY - minSide * 0.012 + Math.sin((wx - cx) * waveFreq * 0.85 - backPhase + 1.0) * (waveAmp * 0.78);
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(cx + portholeR, cy + portholeR);
  ctx.closePath();
  ctx.fillStyle = "#173A7A";
  ctx.fill();

  // Sky Beacon Confirmation Arcs above buoy antenna (Scene 2, strictly inside upper porthole sky)
  if (skyPing > 0.02) {
    const beaconOffset = minSide * 0.104;
    const antX = cx + Math.sin(buoyTilt) * beaconOffset;
    const antY = buoyY - Math.cos(buoyTilt) * beaconOffset;
    for (let k = 0; k < 2; k++) {
      const kProg = (cycleNorm * 4 + k * 0.5) % 1;
      const kAlpha = Math.sin(Math.PI * kProg) * skyPing * 0.85;
      if (kAlpha > 0.03) {
        const kr = minSide * (0.024 + 0.038 * kProg);
        ctx.beginPath();
        ctx.arc(antX, antY, kr, -Math.PI * 0.78 + buoyTilt, -Math.PI * 0.22 + buoyTilt);
        ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
        ctx.strokeStyle = "rgba(52, 211, 153, " + kAlpha.toFixed(3) + ")";
        ctx.stroke();
      }
    }
  }

  // Underwater Sonar Scanning Arcs (Emitted strictly downward from underwater collector pod)
  if (sonarActive > 0.01) {
    const sonarY = buoyY + minSide * 0.048;
    for (let s = 0; s < 2; s++) {
      const sProg = (cycleNorm * 3 + s * 0.5) % 1;
      const sAlpha = Math.sin(Math.PI * sProg) * sonarActive * 0.75;
      if (sAlpha > 0.03) {
        const sr = minSide * (0.042 + 0.088 * sProg);
        ctx.beginPath();
        ctx.arc(cx, sonarY, sr, Math.PI * 0.22, Math.PI * 0.78);
        ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
        ctx.strokeStyle = "rgba(125, 211, 252, " + sAlpha.toFixed(3) + ")";
        ctx.stroke();
      }
    }
  }

  // Underwater Micro-Debris Geometric Shapes (Drawn strictly inside water, pulled cleanly into collector)
  if (debrisVis > 0.01) {
    const debrisSeeds = [
      { side: -1, xStart: -0.145, yOff: 0.085, kind: 0, rot: 0.4 },
      { side: -1, xStart: -0.105, yOff: 0.135, kind: 1, rot: 1.1 },
      { side: 1, xStart: 0.145, yOff: 0.090, kind: 1, rot: 0.7 },
      { side: 1, xStart: 0.105, yOff: 0.138, kind: 0, rot: 1.6 },
    ];
    const targetX = cx;
    const targetY = buoyY + minSide * 0.068;

    for (let i = 0; i < debrisSeeds.length; i++) {
      const d = debrisSeeds[i];
      const pull = clamp01((debrisPull - i * 0.05) / 0.85);
      const startX = cx + d.xStart * minSide;
      const startY = waterBaseY + d.yOff * minSide;
      const px = lerp(startX, targetX + d.side * minSide * 0.012, pull);
      const py = lerp(startY, targetY, pull * pull * 0.7 + pull * 0.3) + Math.sin(cycleNorm * Math.PI * 2 * 4 + i) * minSide * 0.004 * (1 - pull);
      const sz = minSide * 0.010 * (1 - pull * 0.75) * debrisVis;
      const alpha = debrisVis * (1 - smoothRange(pull, 0.75, 1.0));

      if (alpha > 0.04 && sz > 0.8) {
        ctx.save();
        ctx.translate(px, py);
        ctx.rotate(d.rot + cycleNorm * Math.PI * 2 * d.side);
        ctx.globalAlpha = alpha;
        if (d.kind === 0) {
          roundedRectPath(-sz, -sz * 0.65, sz * 2, sz * 1.3, sz * 0.25);
          ctx.fillStyle = "#CBD5E1";
          ctx.fill();
        } else {
          ctx.beginPath();
          ctx.moveTo(0, -sz);
          ctx.lineTo(sz * 0.9, sz * 0.8);
          ctx.lineTo(-sz * 0.9, sz * 0.8);
          ctx.closePath();
          ctx.fillStyle = "#A78BFA";
          ctx.fill();
        }
        ctx.restore();
      }
    }
  }

  // 5. Smart Ocean Buoy & Underwater Collector Assembly (Coupled to buoyY and buoyTilt!)
  ctx.save();
  ctx.translate(cx, buoyY);
  ctx.rotate(buoyTilt);

  // Subsurface Collector Pod (below waterline y > 0)
  const podW = minSide * 0.052;
  const podH = minSide * 0.072;
  const podTop = minSide * 0.012;
  roundedRectPath(-podW * 0.5, podTop, podW, podH, minSide * 0.016);
  ctx.fillStyle = "#0F172A";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
  ctx.strokeStyle = "#38BDF8";
  ctx.stroke();

  // Animated Mechanical Intake Flaps on Left & Right of Underwater Collector Pod
  const flapAngle = intakeOpen * 0.52;
  for (let side = -1; side <= 1; side += 2) {
    ctx.save();
    ctx.translate(side * (podW * 0.5), podTop + podH * 0.56);
    ctx.rotate(side * flapAngle);
    roundedRectPath(side === 1 ? 0 : -minSide * 0.018, -minSide * 0.005, minSide * 0.018, minSide * 0.010, minSide * 0.004);
    ctx.fillStyle = intakeOpen > 0.1 ? "#22D3EE" : "#64748B";
    ctx.fill();
    ctx.restore();
  }

  // Collector core indicator bar inside pod
  roundedRectPath(-podW * 0.22, podTop + minSide * 0.016, podW * 0.44, podH - minSide * 0.032, minSide * 0.006);
  ctx.fillStyle = lerpColor([56, 189, 248], [52, 211, 153], cleanState);
  ctx.fill();

  // Floating Coral Buoy Hull (Straddles waterline cleanly with wide stabilizer collar)
  const hullW = minSide * 0.112;
  const hullH = minSide * 0.044;
  const hullTop = -minSide * 0.022;
  roundedRectPath(-hullW * 0.5, hullTop, hullW, hullH, minSide * 0.018);
  ctx.fillStyle = "#FF6B35";
  ctx.fill();

  // Shaded right third on buoy hull
  ctx.save();
  roundedRectPath(-hullW * 0.5, hullTop, hullW, hullH, minSide * 0.018);
  ctx.clip();
  ctx.fillStyle = "#C2410C";
  ctx.fillRect(hullW * 0.16, hullTop, hullW * 0.4, hullH);
  // Crisp white safety stripe across collar
  ctx.fillStyle = "#F8FAFC";
  ctx.fillRect(-hullW * 0.5, hullTop + hullH * 0.34, hullW, hullH * 0.24);
  ctx.restore();

  roundedRectPath(-hullW * 0.5, hullTop, hullW, hullH, minSide * 0.018);
  ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
  ctx.strokeStyle = "#F8FAFC";
  ctx.stroke();

  // Upper Tapered Mast & Beacon Dome
  const mastTop = hullTop - minSide * 0.068;
  ctx.beginPath();
  ctx.moveTo(-minSide * 0.020, hullTop);
  ctx.lineTo(-minSide * 0.009, mastTop);
  ctx.lineTo(minSide * 0.009, mastTop);
  ctx.lineTo(minSide * 0.020, hullTop);
  ctx.closePath();
  ctx.fillStyle = "#E2E8F0";
  ctx.fill();

  // Beacon Light Housing
  const beaconY = mastTop - minSide * 0.014;
  const beaconColor = lerpColor([251, 191, 36], [52, 211, 153], cleanState);
  ctx.beginPath();
  ctx.arc(0, beaconY, minSide * 0.015, 0, Math.PI * 2);
  ctx.fillStyle = beaconColor;
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.0034);
  ctx.strokeStyle = "#F8FAFC";
  ctx.stroke();

  ctx.restore();

  // 6. Front Translucent Turquoise Ocean Wave (Submerges lower buoy & pod naturally!)
  ctx.beginPath();
  ctx.moveTo(cx - portholeR, cy + portholeR);
  for (let s = 0; s <= wSteps; s++) {
    const u = s / wSteps;
    const wx = cx - portholeR + u * portholeR * 2;
    const wy = frontWaveY(wx);
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(cx + portholeR, cy + portholeR);
  ctx.closePath();

  const seaGrad = ctx.createLinearGradient(cx, waterBaseY - waveAmp, cx, cy + portholeR);
  seaGrad.addColorStop(0, "rgba(6, 182, 212, 0.56)");
  seaGrad.addColorStop(0.55, "rgba(2, 132, 199, 0.68)");
  seaGrad.addColorStop(1, "rgba(29, 78, 216, 0.78)");
  ctx.fillStyle = seaGrad;
  ctx.fill();

  // Crisp opaque Seafoam White wave crest line
  ctx.beginPath();
  for (let s = 0; s <= wSteps; s++) {
    const u = s / wSteps;
    const wx = cx - portholeR + u * portholeR * 2;
    const wy = frontWaveY(wx);
    if (s === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.lineWidth = Math.max(2, minSide * 0.0046);
  ctx.strokeStyle = "#BAE6FD";
  ctx.stroke();

  ctx.restore();

  // Crisp Outer Marine Porthole Frame
  ctx.beginPath();
  ctx.arc(cx, cy, portholeR, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.0085;
  ctx.strokeStyle = "#E0F7FA";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, cy, portholeR - minSide * 0.011, 0, Math.PI * 2);
  ctx.lineWidth = Math.max(1.2, minSide * 0.0024);
  ctx.strokeStyle = "rgba(125, 211, 252, 0.35)";
  ctx.stroke();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function traceHexagon(hx, hy, hr) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = (i * Math.PI) / 3 - Math.PI / 6;
      const px = hx + Math.cos(a) * hr;
      const py = hy + Math.sin(a) * hr;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#140A12");
  bgGrad.addColorStop(0.52, "#200E1B");
  bgGrad.addColorStop(1, "#2E1324");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let sunIntensity = 0.35;
  let photonAlpha = 0;
  let panelTilt = -0.10;
  let cellRipple = 0.15;
  let storageLevel = 0.18;
  let conduitPulse = 0;
  let exportPulse = 0;

  if (currentScene === 0) {
    // Scene 0: Sun rays intensify, photon beams descend, panel tracks toward sun, cells ignite
    sunIntensity = 0.35 + 0.65 * smoothRange(sceneProgress, 0.04, 0.72);
    photonAlpha = smoothRange(sceneProgress, 0.18, 0.85);
    panelTilt = lerp(-0.10, 0.09, easeInOutSine(sceneProgress));
    cellRipple = 0.15 + 0.50 * smoothRange(sceneProgress, 0.24, 0.98);
    storageLevel = 0.18 + 0.34 * smoothRange(sceneProgress, 0.36, 0.98);
    conduitPulse = smoothRange(sceneProgress, 0.32, 0.92);
    exportPulse = 0;
  } else if (currentScene === 1) {
    // Scene 1: Panel aligns horizontally at peak focus, full honeycomb ripple & storage fill
    sunIntensity = 1.0 - 0.18 * smoothRange(sceneProgress, 0.75, 1.0);
    photonAlpha = 1.0 - 0.65 * smoothRange(sceneProgress, 0.68, 1.0);
    panelTilt = lerp(0.09, 0.0, smoothRange(sceneProgress, 0.0, 0.70));
    cellRipple = 0.65 + 0.35 * smoothRange(sceneProgress, 0.0, 0.72);
    storageLevel = 0.52 + 0.48 * smoothRange(sceneProgress, 0.05, 0.82);
    conduitPulse = 1.0 - 0.25 * smoothRange(sceneProgress, 0.76, 1.0);
    exportPulse = smoothRange(sceneProgress, 0.72, 1.0);
  } else {
    // Scene 2: Clean lateral radar energy distribution from charged storage module, smooth reset
    sunIntensity = 0.82 - 0.47 * smoothRange(sceneProgress, 0.18, 0.92);
    photonAlpha = 0.35 * (1 - smoothRange(sceneProgress, 0.0, 0.32));
    panelTilt = lerp(0.0, -0.10, smoothRange(sceneProgress, 0.22, 0.94));
    cellRipple = 1.0 - 0.85 * smoothRange(sceneProgress, 0.20, 0.94);
    storageLevel = 1.0 - 0.82 * smoothRange(sceneProgress, 0.24, 0.95);
    conduitPulse = 0.75 * (1 - smoothRange(sceneProgress, 0.18, 0.78));
    exportPulse = 1.0 - smoothRange(sceneProgress, 0.55, 0.90);
  }

  // 3. Layout Coordinates (Strict vertical & horizontal clearances)
  const cx = width * 0.5;
  const sunY = height * 0.235;
  const sunR = minSide * 0.044;

  const panelCy = height * 0.535;
  const panelW = minSide * 0.340;
  const panelH = minSide * 0.162;

  const modTop = height * 0.705;
  const modH = minSide * 0.115;
  const modW = minSide * 0.295;
  const modCy = modTop + modH * 0.5;

  // 4. Sunburst Disk & Crisp Corona Rays (Top Zone)
  const rayCount = 8;
  const rayInner = sunR + minSide * 0.016;
  const rayBaseLen = minSide * 0.020;
  const rayOsc = Math.sin(cycleNorm * Math.PI * 2 * 6);

  for (let i = 0; i < rayCount; i++) {
    const a = (i * Math.PI * 2) / rayCount + cycleNorm * Math.PI * 2 * 0.25; // 2-fold? Wait: 8-fold symmetry * 0.25 rev = 2 teeth = 100% seamless!
    const alt = i % 2 === 0 ? rayOsc : -rayOsc;
    const len = rayBaseLen * (0.65 + 0.55 * sunIntensity + 0.15 * alt);
    const x0 = cx + Math.cos(a) * rayInner;
    const y0 = sunY + Math.sin(a) * rayInner;
    const x1 = cx + Math.cos(a) * (rayInner + len);
    const y1 = sunY + Math.sin(a) * (rayInner + len);

    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.lineTo(x1, y1);
    ctx.lineWidth = Math.max(1.8, minSide * 0.0048);
    ctx.strokeStyle = i % 2 === 0 ? "#FFE066" : "#FF9F1C";
    ctx.stroke();
  }

  // Two-tone flat-vector sun disk
  ctx.beginPath();
  ctx.arc(cx, sunY, sunR, 0, Math.PI * 2);
  ctx.fillStyle = "#FF9F1C";
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, sunY, sunR, 0, Math.PI * 2);
  ctx.clip();
  ctx.beginPath();
  ctx.arc(cx - sunR * 0.18, sunY - sunR * 0.18, sunR * 0.92, 0, Math.PI * 2);
  ctx.fillStyle = "#FFE066";
  ctx.fill();
  ctx.restore();

  ctx.beginPath();
  ctx.arc(cx, sunY, sunR, 0, Math.PI * 2);
  ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
  ctx.strokeStyle = "#FEF3C7";
  ctx.stroke();

  // 5. Symmetrical Photon Stream Corridor (Strictly between sun bottom ray 0.330*H and tilted panel top 0.430*H)
  if (photonAlpha > 0.01) {
    const startY = sunY + rayInner + minSide * 0.036;
    const endY = panelCy - minSide * 0.116; // Safe clearance above tilted panel edge!
    const lanes = [
      { off: -0.075, phase: 0.0 },
      { off: 0.0, phase: 0.5 },
      { off: 0.075, phase: 0.0 },
    ];

    for (let i = 0; i < lanes.length; i++) {
      const pNorm = (cycleNorm * 5 + lanes[i].phase) % 1;
      const alpha = Math.sin(Math.PI * pNorm) * photonAlpha * 0.92;
      if (alpha > 0.03) {
        const px = cx + lanes[i].off * minSide;
        const py = lerp(startY, endY, pNorm);
        const plen = minSide * 0.022;
        ctx.beginPath();
        ctx.moveTo(px, py);
        ctx.lineTo(px, py + plen);
        ctx.lineWidth = minSide * 0.0052;
        ctx.strokeStyle = "rgba(255, 224, 102, " + alpha.toFixed(3) + ")";
        ctx.stroke();
      }
    }
  }

  // 6. Vertical Pedestal Strut & Energy Conduit (Behind tilted solar panel, anchored cleanly into base storage)
  const strutW = minSide * 0.028;
  ctx.fillStyle = "#475569";
  ctx.fillRect(cx - strutW * 0.5, panelCy, strutW, modTop - panelCy + minSide * 0.006);

  // Subtle right flat shading on strut
  ctx.fillStyle = "#334155";
  ctx.fillRect(cx, panelCy, strutW * 0.5, modTop - panelCy + minSide * 0.006);

  // Inner power conduit channel visible below panel edge down into storage module
  const condTop = panelCy + minSide * 0.088;
  const condBot = modTop - minSide * 0.004;
  ctx.beginPath();
  ctx.moveTo(cx, condTop);
  ctx.lineTo(cx, condBot);
  ctx.lineWidth = minSide * 0.007;
  ctx.strokeStyle = "#1E1B2E";
  ctx.stroke();

  if (conduitPulse > 0.02) {
    const pNorm = (cycleNorm * 6) % 1;
    const py = lerp(condTop + minSide * 0.008, condBot - minSide * 0.006, pNorm);
    const alpha = Math.sin(Math.PI * pNorm) * conduitPulse;
    if (alpha > 0.03) {
      ctx.beginPath();
      ctx.arc(cx, py, minSide * 0.0055, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(34, 211, 238, " + alpha.toFixed(3) + ")";
      ctx.fill();
    }
  }

  // 7. Articulated Photovoltaic Hexagonal Solar Panel (Tilts smoothly around center pivot)
  ctx.save();
  ctx.translate(cx, panelCy);
  ctx.rotate(panelTilt);

  const pLeft = -panelW * 0.5;
  const pTop = -panelH * 0.5;
  const pR = minSide * 0.020;

  roundedRectPath(pLeft, pTop, panelW, panelH, pR);
  ctx.fillStyle = "#0F172A";
  ctx.fill();

  // Inner clipped hexagonal photovoltaic grid
  const pad = minSide * 0.012;
  ctx.save();
  roundedRectPath(pLeft + pad, pTop + pad, panelW - pad * 2, panelH - pad * 2, pR * 0.65);
  ctx.clip();

  ctx.fillStyle = "#11224D";
  ctx.fillRect(pLeft + pad, pTop + pad, panelW - pad * 2, panelH - pad * 2);

  // Honeycomb 2 rows x 5 cols cleanly fitted inside panel interior
  const hexR = minSide * 0.025;
  const cols = 5;
  const rows = 2;
  const stepX = minSide * 0.056;
  const stepY = minSide * 0.052;
  const maxRadialDist = Math.hypot((cols - 1) * 0.5 * stepX, 0.5 * stepY);

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const hx = (c - (cols - 1) * 0.5) * stepX;
      const hy = (r - (rows - 1) * 0.5) * stepY;
      const distNorm = Math.hypot(hx, hy) / (maxRadialDist + 0.001);
      const cellLit = clamp01((cellRipple - distNorm * 0.55) * 2.2);

      traceHexagon(hx, hy, hexR);
      ctx.fillStyle = lerpColor([22, 46, 110], [34, 211, 238], cellLit);
      ctx.fill();

      if (cellLit > 0.45) {
        traceHexagon(hx, hy, hexR * 0.46);
        ctx.fillStyle = "rgba(254, 240, 138, " + ((cellLit - 0.45) * 0.9).toFixed(3) + ")";
        ctx.fill();
      }

      traceHexagon(hx, hy, hexR);
      ctx.lineWidth = Math.max(1.2, minSide * 0.0024);
      ctx.strokeStyle = lerpColor([56, 189, 248], [254, 240, 138], cellLit * 0.55);
      ctx.stroke();
    }
  }

  // Subtle diagonal glass highlight stripe
  ctx.beginPath();
  ctx.moveTo(pLeft + panelW * 0.12, pTop);
  ctx.lineTo(pLeft + panelW * 0.24, pTop);
  ctx.lineTo(pLeft + panelW * 0.08, pTop + panelH);
  ctx.lineTo(pLeft - panelW * 0.04, pTop + panelH);
  ctx.closePath();
  ctx.fillStyle = "rgba(255, 255, 255, 0.10)";
  ctx.fill();

  ctx.restore();

  // Outer panel titanium rim
  roundedRectPath(pLeft, pTop, panelW, panelH, pR);
  ctx.lineWidth = minSide * 0.0068;
  ctx.strokeStyle = "#E2E8F0";
  ctx.stroke();

  ctx.restore();

  // 8. Base Energy Storage Module & Lateral Radar Export Waves (Strictly flanking left & right)
  if (exportPulse > 0.01) {
    for (let side = -1; side <= 1; side += 2) {
      const baseAng = side === 1 ? 0 : Math.PI;
      for (let w = 0; w < 2; w++) {
        const wProg = (cycleNorm * 4 + w * 0.5) % 1;
        const wAlpha = Math.sin(Math.PI * wProg) * exportPulse * 0.85;
        if (wAlpha > 0.03) {
          const rArc = modW * 0.5 + minSide * (0.020 + 0.038 * wProg);
          const arcSpan = 0.28;
          ctx.beginPath();
          ctx.arc(cx, modCy, rArc, baseAng - arcSpan, baseAng + arcSpan);
          ctx.lineWidth = Math.max(1.5, minSide * 0.0036);
          ctx.strokeStyle = "rgba(34, 211, 238, " + wAlpha.toFixed(3) + ")";
          ctx.stroke();
        }
      }
    }
  }

  const modLeft = cx - modW * 0.5;
  const modR = minSide * 0.020;
  roundedRectPath(modLeft, modTop, modW, modH, modR);
  ctx.fillStyle = "#171122";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0058;
  ctx.strokeStyle = "#94A3B8";
  ctx.stroke();

  // 6 vertical segmented storage bars inside base module
  const barCount = 6;
  const barGap = minSide * 0.011;
  const innerPad = minSide * 0.024;
  const availW = modW - innerPad * 2;
  const barW = (availW - (barCount - 1) * barGap) / barCount;
  const barH = modH - minSide * 0.036;
  const barTopY = modTop + (modH - barH) * 0.5;

  for (let b = 0; b < barCount; b++) {
    const bx = modLeft + innerPad + b * (barW + barGap);
    roundedRectPath(bx, barTopY, barW, barH, barW * 0.35);
    ctx.fillStyle = "#261B38";
    ctx.fill();

    const segFill = clamp01((storageLevel - b / barCount) * barCount);
    if (segFill > 0.02) {
      const fh = barH * segFill;
      roundedRectPath(bx, barTopY + (barH - fh), barW, fh, barW * 0.35);
      ctx.fillStyle = b >= 4 ? "#FFE066" : "#22D3EE";
      ctx.fill();
    }
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  // Terrarium bowl path: flat rounded top rim, curved lower basin
  function traceSoilBowlPath(cx, topY, halfW, botY, topR) {
    const h = botY - topY;
    ctx.beginPath();
    ctx.moveTo(cx - halfW + topR, topY);
    ctx.lineTo(cx + halfW - topR, topY);
    ctx.quadraticCurveTo(cx + halfW, topY, cx + halfW, topY + topR);
    ctx.bezierCurveTo(
      cx + halfW,
      topY + h * 0.62,
      cx + halfW * 0.66,
      botY,
      cx,
      botY
    );
    ctx.bezierCurveTo(
      cx - halfW * 0.66,
      botY,
      cx - halfW,
      topY + h * 0.62,
      cx - halfW,
      topY + topR
    );
    ctx.quadraticCurveTo(cx - halfW, topY, cx - halfW + topR, topY);
    ctx.closePath();
  }

  function drawTrimQuad(x0, y0, cx0, cy0, x1, y1, prog) {
    const p = clamp01(prog);
    if (p <= 0.01) return;
    const steps = 16;
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const s = (i / steps) * p;
      const omt = 1 - s;
      const px = omt * omt * x0 + 2 * omt * s * cx0 + s * s * x1;
      const py = omt * omt * y0 + 2 * omt * s * cy0 + s * s * y1;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
  }

  function drawLeaf(x, y, angle, length, widthFactor, openAmt, colorLeft, colorRight, borderColor, borderW) {
    if (openAmt <= 0.008 || length <= 0.5) return;
    const len = length * openAmt;
    const halfW = len * widthFactor;

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(len * 0.28, -halfW, len * 0.76, -halfW * 0.72, len, 0);
    ctx.bezierCurveTo(len * 0.76, halfW * 0.72, len * 0.28, halfW, 0, 0);
    ctx.closePath();
    ctx.lineWidth = borderW;
    ctx.strokeStyle = borderColor;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(len * 0.28, -halfW, len * 0.76, -halfW * 0.72, len, 0);
    ctx.lineTo(0, 0);
    ctx.closePath();
    ctx.fillStyle = colorLeft;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(len, 0);
    ctx.bezierCurveTo(len * 0.76, halfW * 0.72, len * 0.28, halfW, 0, 0);
    ctx.closePath();
    ctx.fillStyle = colorRight;
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(len * 0.14, 0);
    ctx.lineTo(len * 0.78, 0);
    ctx.lineWidth = Math.max(1, minSide * 0.0022);
    ctx.strokeStyle = "#F7FEE7";
    ctx.stroke();

    ctx.restore();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#14110B");
  bgGrad.addColorStop(0.52, "#1E1910");
  bgGrad.addColorStop(1, "#292115");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  // Scene 0: Cloud transitions to storm blue & rains into soil; roots begin branching; moisture rises.
  // Scene 1: Rain stops completely before sprout rises; stem & leaves unfold cleanly in open air; roots finish.
  // Scene 2: Crown bloom opens, oxygen/vapor orbs rise in outer side lanes back to cloud; smooth reset to seed state.
  let cloudRainTint = 0;
  let cloudScale = 1;
  let rainAlpha = 0;
  let moistureLevel = 0.18;
  let rootGrowth = 0;
  let stemGrowth = 0;
  let leaf1Open = 0;
  let leaf2Open = 0;
  let crownOpen = 0;
  let vaporActive = 0;

  if (currentScene === 0) {
    cloudRainTint = smoothRange(sceneProgress, 0.04, 0.28);
    cloudScale = 1 + 0.06 * Math.sin(Math.PI * smoothRange(sceneProgress, 0.04, 0.90));
    rainAlpha = Math.sin(Math.PI * clamp01((sceneProgress - 0.12) / 0.80));
    moistureLevel = 0.18 + 0.74 * smoothRange(sceneProgress, 0.16, 0.94);
    rootGrowth = 0.58 * smoothRange(sceneProgress, 0.30, 0.98);
    stemGrowth = 0;
    leaf1Open = 0;
    leaf2Open = 0;
    crownOpen = 0;
    vaporActive = 0;
  } else if (currentScene === 1) {
    cloudRainTint = 1 - smoothRange(sceneProgress, 0.02, 0.40);
    cloudScale = 1;
    rainAlpha = 0;
    moistureLevel = 0.92 - 0.14 * smoothRange(sceneProgress, 0.20, 1.0);
    rootGrowth = 0.58 + 0.42 * smoothRange(sceneProgress, 0.0, 0.55);
    stemGrowth = smoothRange(sceneProgress, 0.08, 0.68);
    leaf1Open = smoothRange(sceneProgress, 0.24, 0.66);
    leaf2Open = smoothRange(sceneProgress, 0.46, 0.88);
    crownOpen = smoothRange(sceneProgress, 0.68, 0.98);
    vaporActive = smoothRange(sceneProgress, 0.76, 1.0) * 0.4;
  } else {
    cloudRainTint = 0;
    cloudScale = 1;
    rainAlpha = 0;
    moistureLevel = 0.78 - 0.60 * smoothRange(sceneProgress, 0.28, 0.94);
    rootGrowth = 1 - smoothRange(sceneProgress, 0.36, 0.95);
    stemGrowth = 1 - smoothRange(sceneProgress, 0.32, 0.92);
    leaf1Open = 1 - smoothRange(sceneProgress, 0.24, 0.80);
    leaf2Open = 1 - smoothRange(sceneProgress, 0.14, 0.68);
    crownOpen = 1 - smoothRange(sceneProgress, 0.05, 0.54);
    vaporActive = 0.4 + 0.6 * Math.sin(Math.PI * clamp01(sceneProgress / 0.68));
    if (sceneProgress >= 0.68) {
      vaporActive = 0.4 * (1 - smoothRange(sceneProgress, 0.68, 0.92));
    }
  }

  const leafSway = Math.sin(cycleNorm * Math.PI * 2 * 3) * 0.04;

  // 3. Layout Coordinates (Strict non-overlapping vertical & horizontal zones)
  const cx = width * 0.5;
  const cloudY = height * 0.265;
  const soilTopY = height * 0.605;
  const soilBotY = height * 0.835;
  const soilHalfW = minSide * 0.168;
  const soilTopR = minSide * 0.022;

  // 4. Raindrops Zone (Scene 0 ONLY, cleanly between cloud bottom and soil surface)
  if (rainAlpha > 0.01) {
    const rainStartY = cloudY + minSide * 0.045;
    const rainEndY = soilTopY - minSide * 0.010;
    const dropLanes = [-0.062, 0.0, 0.062];

    for (let i = 0; i < dropLanes.length; i++) {
      const phaseShift = i === 1 ? 0.5 : 0.0;
      for (let d = 0; d < 2; d++) {
        const prog = (cycleNorm * 6 + phaseShift + d * 0.5) % 1;
        const dy = lerp(rainStartY, rainEndY, prog);
        const dx = cx + dropLanes[i] * minSide;
        const dAlpha = Math.sin(Math.PI * prog) * rainAlpha * 0.92;
        if (dAlpha > 0.03) {
          const dr = minSide * 0.0072;
          ctx.beginPath();
          ctx.moveTo(dx, dy - dr * 1.65);
          ctx.quadraticCurveTo(dx + dr, dy + dr * 0.15, dx, dy + dr);
          ctx.quadraticCurveTo(dx - dr, dy + dr * 0.15, dx, dy - dr * 1.65);
          ctx.closePath();
          ctx.fillStyle = "rgba(56, 189, 248, " + dAlpha.toFixed(3) + ")";
          ctx.fill();
        }
      }
    }

    // Crisp symmetrical water-drop surface ripple cleanly above soil rim
    const splashProg = (cycleNorm * 6) % 1;
    const splashAlpha = Math.sin(Math.PI * splashProg) * rainAlpha * 0.72;
    if (splashAlpha > 0.03) {
      const spW = minSide * (0.014 + 0.042 * splashProg);
      const spY = soilTopY - minSide * 0.018;
      ctx.beginPath();
      ctx.moveTo(cx - spW, spY);
      ctx.lineTo(cx - spW * 0.35, spY);
      ctx.moveTo(cx + spW * 0.35, spY);
      ctx.lineTo(cx + spW, spY);
      ctx.lineWidth = Math.max(1.5, minSide * 0.003);
      ctx.strokeStyle = "rgba(56, 189, 248, " + splashAlpha.toFixed(3) + ")";
      ctx.stroke();
    }
  }

  // 5. Rising Vapor / Oxygen Particles in Outer Margin Lanes ONLY (x = cx ± 0.125 * minSide, outside leaf span!)
  if (vaporActive > 0.01) {
    const vapBot = soilTopY - minSide * 0.035;
    const vapTop = cloudY + minSide * 0.052;
    const vapLanes = [-0.125, 0.125];
    for (let i = 0; i < vapLanes.length; i++) {
      for (let k = 0; k < 2; k++) {
        const prog = (cycleNorm * 4 + k * 0.5 + i * 0.25) % 1;
        const vy = lerp(vapBot, vapTop, prog);
        const vx = cx + vapLanes[i] * minSide + Math.sin(prog * Math.PI * 2) * minSide * 0.005 * (i === 0 ? -1 : 1);
        const vAlpha = Math.sin(Math.PI * prog) * vaporActive * 0.85;
        if (vAlpha > 0.03) {
          ctx.beginPath();
          ctx.arc(vx, vy, minSide * 0.0055, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(163, 230, 53, " + vAlpha.toFixed(3) + ")";
          ctx.fill();
        }
      }
    }
  }

  // 6. Growing Sprout Stem & Two-Tone Flat Vector Leaves (Peaks cleanly at height * 0.365, well below cloud!)
  const maxStemH = minSide * 0.235;
  const sproutTopY = soilTopY - maxStemH * stemGrowth;
  if (stemGrowth > 0.01) {
    const stemBorderW = minSide * 0.011;
    const stemCoreW = minSide * 0.0055;

    ctx.beginPath();
    ctx.moveTo(cx, soilTopY + minSide * 0.006);
    ctx.lineTo(cx, sproutTopY);
    ctx.lineWidth = stemBorderW;
    ctx.strokeStyle = "#18130B";
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(cx, soilTopY + minSide * 0.006);
    ctx.lineTo(cx, sproutTopY);
    ctx.lineWidth = stemCoreW;
    ctx.strokeStyle = "#D9F99D";
    ctx.stroke();

    const leafBorderW = minSide * 0.007;
    const yL1 = lerp(soilTopY, sproutTopY, 0.36);
    const yL2 = lerp(soilTopY, sproutTopY, 0.70);

    drawLeaf(cx - minSide * 0.002, yL1, -Math.PI * 0.78 + leafSway, minSide * 0.072, 0.35, leaf1Open, "#BEF264", "#22C55E", "#18130B", leafBorderW);
    drawLeaf(cx + minSide * 0.002, yL1, -Math.PI * 0.22 - leafSway, minSide * 0.072, 0.35, leaf1Open, "#22C55E", "#BEF264", "#18130B", leafBorderW);

    drawLeaf(cx - minSide * 0.002, yL2, -Math.PI * 0.74 - leafSway * 0.8, minSide * 0.058, 0.35, leaf2Open, "#D9F99D", "#4ADE80", "#18130B", leafBorderW);
    drawLeaf(cx + minSide * 0.002, yL2, -Math.PI * 0.26 + leafSway * 0.8, minSide * 0.058, 0.35, leaf2Open, "#4ADE80", "#D9F99D", "#18130B", leafBorderW);

    // Crown triple bud leaf at top
    drawLeaf(cx, sproutTopY + minSide * 0.002, -Math.PI * 0.5 + leafSway * 0.5, minSide * 0.048, 0.38, crownOpen, "#FEF08A", "#A3E635", "#18130B", leafBorderW);
  }

  // 7. Soil Terrarium Bowl (Clipped Strata, Seed Core, Branching Roots)
  traceSoilBowlPath(cx, soilTopY, soilHalfW, soilBotY, soilTopR);
  ctx.fillStyle = "#3B1E12";
  ctx.fill();

  ctx.save();
  traceSoilBowlPath(cx, soilTopY, soilHalfW, soilBotY, soilTopR);
  ctx.clip();

  // Layered flat-vector soil strata bands
  const soilH = soilBotY - soilTopY;
  ctx.fillStyle = "#C87A55";
  ctx.fillRect(cx - soilHalfW, soilTopY, soilHalfW * 2, soilH * 0.26);

  ctx.fillStyle = "#8B4B2E";
  ctx.fillRect(cx - soilHalfW, soilTopY + soilH * 0.24, soilHalfW * 2, soilH * 0.34);

  ctx.fillStyle = "#532B19";
  ctx.fillRect(cx - soilHalfW, soilTopY + soilH * 0.56, soilHalfW * 2, soilH * 0.46);

  // Subtle flat-vector right-third shadow overlay on soil bowl
  ctx.fillStyle = "rgba(18, 12, 8, 0.24)";
  ctx.fillRect(cx + soilHalfW * 0.36, soilTopY, soilHalfW * 0.65, soilH);

  // Underground Branching Roots (Trim-path curve growth from seed core)
  const seedY = soilTopY + soilH * 0.28;
  if (rootGrowth > 0.01) {
    ctx.strokeStyle = "#FDBA74";
    ctx.lineWidth = Math.max(1.8, minSide * 0.0042);

    const pMain = clamp01(rootGrowth / 0.65);
    const pSub = clamp01((rootGrowth - 0.35) / 0.65);

    // Left and right main roots
    drawTrimQuad(cx, seedY, cx - soilHalfW * 0.35, seedY + soilH * 0.16, cx - soilHalfW * 0.56, seedY + soilH * 0.48, pMain);
    drawTrimQuad(cx, seedY, cx + soilHalfW * 0.35, seedY + soilH * 0.16, cx + soilHalfW * 0.56, seedY + soilH * 0.48, pMain);
    // Central taproot
    drawTrimQuad(cx, seedY, cx - soilHalfW * 0.06, seedY + soilH * 0.30, cx, seedY + soilH * 0.56, pMain);

    if (pSub > 0.01) {
      ctx.lineWidth = Math.max(1.2, minSide * 0.0028);
      ctx.strokeStyle = "#FED7AA";
      drawTrimQuad(cx - soilHalfW * 0.28, seedY + soilH * 0.18, cx - soilHalfW * 0.18, seedY + soilH * 0.36, cx - soilHalfW * 0.24, seedY + soilH * 0.52, pSub);
      drawTrimQuad(cx + soilHalfW * 0.28, seedY + soilH * 0.18, cx + soilHalfW * 0.18, seedY + soilH * 0.36, cx + soilHalfW * 0.24, seedY + soilH * 0.52, pSub);
    }
  }

  // Luminous Seed Core nestled in upper loam
  ctx.beginPath();
  ctx.ellipse(cx, seedY, minSide * 0.018, minSide * 0.013, 0, 0, Math.PI * 2);
  ctx.fillStyle = "#FEF08A";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
  ctx.strokeStyle = "#3B1E12";
  ctx.stroke();

  ctx.restore();

  // Crisp Terrarium Rim Outline
  traceSoilBowlPath(cx, soilTopY, soilHalfW, soilBotY, soilTopR);
  ctx.lineWidth = minSide * 0.0072;
  ctx.strokeStyle = "#E7E5E4";
  ctx.stroke();

  // 8. Rain Cloud Icon at Top (Exact circle-intersection silhouette — zero bridging lines, zero seams!)
  const cloudBaseColor = lerpColor([226, 232, 240], [56, 189, 248], cloudRainTint);
  const cloudShadeColor = lerpColor([182, 196, 214], [20, 146, 198], cloudRainTint);
  const cloudHighlightColor = lerpColor([248, 250, 252], [186, 230, 253], cloudRainTint);

  function upperCircleIntersection(ax, ay, ar, bx, by, br) {
    const dx = bx - ax;
    const dy = by - ay;
    const d = Math.hypot(dx, dy);
    const a = (ar * ar - br * br + d * d) / (2 * d);
    const h = Math.sqrt(Math.max(0, ar * ar - a * a));
    const ux = dx / d;
    const uy = dy / d;
    const mx = ax + a * ux;
    const my = ay + a * uy;
    const p1x = mx + h * uy;
    const p1y = my - h * ux;
    const p2x = mx - h * uy;
    const p2y = my + h * ux;
    return p1y <= p2y ? { x: p1x, y: p1y } : { x: p2x, y: p2y };
  }

  ctx.save();
  ctx.translate(cx, cloudY);
  ctx.scale(cloudScale, cloudScale);

  const cBot = minSide * 0.032;
  const rL = minSide * 0.031;
  const xL = -minSide * 0.068;
  const yL = cBot - rL;

  const rM1 = minSide * 0.045;
  const xM1 = -minSide * 0.014;
  const yM1 = cBot - minSide * 0.042;

  const rM2 = minSide * 0.035;
  const xM2 = minSide * 0.036;
  const yM2 = cBot - minSide * 0.035;

  const rR = minSide * 0.029;
  const xR = minSide * 0.072;
  const yR = cBot - rR;

  const intR_M2 = upperCircleIntersection(xR, yR, rR, xM2, yM2, rM2);
  const intM2_M1 = upperCircleIntersection(xM2, yM2, rM2, xM1, yM1, rM1);
  const intM1_L = upperCircleIntersection(xM1, yM1, rM1, xL, yL, rL);

  function traceCloudPath() {
    ctx.beginPath();
    ctx.moveTo(xL, cBot);
    ctx.lineTo(xR, cBot);
    ctx.arc(xR, yR, rR, Math.PI * 0.5, Math.atan2(intR_M2.y - yR, intR_M2.x - xR), true);
    ctx.arc(xM2, yM2, rM2, Math.atan2(intR_M2.y - yM2, intR_M2.x - xM2), Math.atan2(intM2_M1.y - yM2, intM2_M1.x - xM2), true);
    ctx.arc(xM1, yM1, rM1, Math.atan2(intM2_M1.y - yM1, intM2_M1.x - xM1), Math.atan2(intM1_L.y - yM1, intM1_L.x - xM1), true);
    ctx.arc(xL, yL, rL, Math.atan2(intM1_L.y - yL, intM1_L.x - xL), Math.PI * 0.5, true);
    ctx.closePath();
  }

  traceCloudPath();
  ctx.fillStyle = cloudBaseColor;
  ctx.fill();

  // Subtle flat-vector base contour shadow & clean upper dome specular arc
  ctx.save();
  traceCloudPath();
  ctx.clip();

  ctx.fillStyle = cloudShadeColor;
  ctx.fillRect(-minSide * 0.12, cBot - minSide * 0.0085, minSide * 0.24, minSide * 0.014);

  ctx.beginPath();
  ctx.arc(xM1, yM1, rM1 * 0.78, -Math.PI * 0.85, -Math.PI * 0.34, false);
  ctx.lineWidth = Math.max(1.5, minSide * 0.0036);
  ctx.strokeStyle = cloudHighlightColor;
  ctx.stroke();

  ctx.restore();

  traceCloudPath();
  ctx.lineWidth = minSide * 0.0052;
  ctx.strokeStyle = "#F8FAFC";
  ctx.stroke();
  ctx.restore();

  // 9. Left Moisture Gauge Bar (Aligned with Soil Bowl, clear separation >= 0.065 * minSide)
  const barX = cx - minSide * 0.245;
  const barW = minSide * 0.016;
  const barTop = soilTopY + minSide * 0.016;
  const barBot = soilBotY - minSide * 0.026;
  const barH = barBot - barTop;

  roundedRectPath(barX - barW * 0.5, barTop, barW, barH, barW * 0.5);
  ctx.fillStyle = "#241D13";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.003);
  ctx.strokeStyle = "#4A3E2A";
  ctx.stroke();

  const fillH = barH * moistureLevel;
  if (fillH > barW * 0.5) {
    roundedRectPath(barX - barW * 0.5 + minSide * 0.002, barBot - fillH + minSide * 0.002, barW - minSide * 0.004, fillH - minSide * 0.004, barW * 0.4);
    ctx.fillStyle = lerpColor([56, 189, 248], [34, 197, 94], clamp01(stemGrowth));
    ctx.fill();
  }

  // 10. Right Growth Cycle Progress Ring Badge (Symmetrical right balance at cx + 0.245 * minSide)
  const badgeX = cx + minSide * 0.245;
  const badgeY = (soilTopY + soilBotY) * 0.5;
  const badgeR = minSide * 0.052;
  const cycleProg = clamp01(Math.max(rootGrowth * 0.35, stemGrowth * 0.65 + crownOpen * 0.35));

  ctx.beginPath();
  ctx.arc(badgeX, badgeY, badgeR, 0, Math.PI * 2);
  ctx.fillStyle = "#1D170E";
  ctx.fill();

  ctx.beginPath();
  ctx.arc(badgeX, badgeY, badgeR - minSide * 0.0065, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.0068;
  ctx.strokeStyle = "#3A3020";
  ctx.stroke();

  const ringSweep = Math.PI * 2 * (0.15 + 0.85 * cycleProg);
  ctx.beginPath();
  ctx.arc(badgeX, badgeY, badgeR - minSide * 0.0065, -Math.PI * 0.5, -Math.PI * 0.5 + ringSweep);
  ctx.lineWidth = minSide * 0.0068;
  ctx.strokeStyle = lerpColor([56, 189, 248], [163, 230, 53], cycleProg);
  ctx.stroke();

  // Mini sprout indicator dot/leaf inside badge
  if (crownOpen > 0.05) {
    drawLeaf(badgeX - badgeR * 0.22, badgeY + badgeR * 0.25, -Math.PI * 0.28, badgeR * 0.72, 0.38, crownOpen, "#BEF264", "#22C55E", "#1D170E", minSide * 0.003);
  } else {
    ctx.beginPath();
    ctx.arc(badgeX, badgeY, badgeR * 0.18, 0, Math.PI * 2);
    ctx.fillStyle = rainAlpha > 0.1 ? "#38BDF8" : "#FDE68A";
    ctx.fill();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawCurvedArrow(cx, cy, midR, thick, startAng, endAng, mainColor, hiColor, headSize) {
    const halfT = thick * 0.5;
    const shaftEndAng = endAng - headSize * 0.52;

    // Rounded tail to shaft end
    ctx.beginPath();
    ctx.arc(cx, cy, midR + halfT, startAng, shaftEndAng, false);
    // Outer wing of arrowhead
    const tipX = cx + Math.cos(endAng) * midR;
    const tipY = cy + Math.sin(endAng) * midR;
    const wingOutX = cx + Math.cos(shaftEndAng) * (midR + halfT * 1.48);
    const wingOutY = cy + Math.sin(shaftEndAng) * (midR + halfT * 1.48);
    const wingInX = cx + Math.cos(shaftEndAng) * (midR - halfT * 1.48);
    const wingInY = cy + Math.sin(shaftEndAng) * (midR - halfT * 1.48);

    ctx.lineTo(wingOutX, wingOutY);
    ctx.lineTo(tipX, tipY);
    ctx.lineTo(wingInX, wingInY);
    ctx.arc(cx, cy, midR - halfT, shaftEndAng, startAng, true);
    ctx.arc(
      cx + Math.cos(startAng) * midR,
      cy + Math.sin(startAng) * midR,
      halfT,
      startAng + Math.PI,
      startAng,
      false
    );
    ctx.closePath();

    ctx.fillStyle = mainColor;
    ctx.fill();

    // Subtle crisp bevel highlight along outer curve of ribbon
    ctx.beginPath();
    ctx.arc(cx, cy, midR + halfT * 0.62, startAng + 0.04, shaftEndAng - 0.04, false);
    ctx.lineWidth = Math.max(1.5, thick * 0.16);
    ctx.strokeStyle = hiColor;
    ctx.stroke();
  }

  function drawGearRing(cx, cy, outerR, innerR, teeth, angle, fillColor, strokeColor) {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);

    ctx.beginPath();
    const step = (Math.PI * 2) / teeth;
    for (let i = 0; i < teeth; i++) {
      const a0 = i * step;
      const a1 = a0 + step * 0.22;
      const a2 = a0 + step * 0.34;
      const a3 = a0 + step * 0.66;
      const a4 = a0 + step * 0.78;
      if (i === 0) ctx.moveTo(Math.cos(a0) * innerR, Math.sin(a0) * innerR);
      else ctx.lineTo(Math.cos(a0) * innerR, Math.sin(a0) * innerR);
      ctx.lineTo(Math.cos(a1) * innerR, Math.sin(a1) * innerR);
      ctx.lineTo(Math.cos(a2) * outerR, Math.sin(a2) * outerR);
      ctx.lineTo(Math.cos(a3) * outerR, Math.sin(a3) * outerR);
      ctx.lineTo(Math.cos(a4) * innerR, Math.sin(a4) * innerR);
    }
    ctx.closePath();
    ctx.fillStyle = fillColor;
    ctx.fill();
    ctx.lineWidth = Math.max(1.5, minSide * 0.0028);
    ctx.strokeStyle = strokeColor;
    ctx.stroke();
    ctx.restore();
  }

  function drawMaterialIcon(kind, x, y, r, alpha) {
    if (alpha <= 0.02 || r <= 0.5) return;
    ctx.save();
    ctx.translate(x, y);
    ctx.globalAlpha = alpha;

    // Clean badge backdrop circle
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.fillStyle = "#0C2920";
    ctx.fill();
    ctx.lineWidth = Math.max(1.2, minSide * 0.0024);

    if (kind === 0) {
      // Bottle silhouette (Teal Turquoise)
      ctx.strokeStyle = "#00B8D9";
      ctx.stroke();
      ctx.fillStyle = "#38BDF8";
      roundedRectPath(-r * 0.28, -r * 0.22, r * 0.56, r * 0.66, r * 0.14);
      ctx.fill();
      roundedRectPath(-r * 0.14, -r * 0.46, r * 0.28, r * 0.26, r * 0.06);
      ctx.fill();
    } else if (kind === 1) {
      // Paper sheet icon (Clean Ivory)
      ctx.strokeStyle = "#94A3B8";
      ctx.stroke();
      ctx.fillStyle = "#E2E8F0";
      roundedRectPath(-r * 0.34, -r * 0.42, r * 0.68, r * 0.84, r * 0.10);
      ctx.fill();
      ctx.strokeStyle = "#0C2920";
      ctx.lineWidth = Math.max(1, r * 0.10);
      ctx.beginPath();
      ctx.moveTo(-r * 0.18, -r * 0.12);
      ctx.lineTo(r * 0.18, -r * 0.12);
      ctx.moveTo(-r * 0.18, r * 0.14);
      ctx.lineTo(r * 0.12, r * 0.14);
      ctx.stroke();
    } else {
      // Metal can / block (Sunburst Gold)
      ctx.strokeStyle = "#FBBF24";
      ctx.stroke();
      ctx.fillStyle = "#FBBF24";
      roundedRectPath(-r * 0.30, -r * 0.40, r * 0.60, r * 0.80, r * 0.14);
      ctx.fill();
      ctx.fillStyle = "#FEF3C7";
      ctx.fillRect(-r * 0.20, -r * 0.08, r * 0.40, r * 0.16);
    }

    ctx.restore();
  }

  function drawEcoLeaf(cx, cy, size, openAmt) {
    if (openAmt <= 0.01) return;
    ctx.save();
    ctx.translate(cx, cy);
    const s = size * openAmt;

    // Two-tone vertical/angled botanical crystal leaf
    ctx.rotate(-Math.PI * 0.18);
    ctx.beginPath();
    ctx.moveTo(0, s * 0.62);
    ctx.bezierCurveTo(-s * 0.72, s * 0.18, -s * 0.56, -s * 0.56, 0, -s * 0.82);
    ctx.lineTo(0, s * 0.62);
    ctx.closePath();
    ctx.fillStyle = "#4ADE80";
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(0, s * 0.62);
    ctx.lineTo(0, -s * 0.82);
    ctx.bezierCurveTo(s * 0.56, -s * 0.56, s * 0.72, s * 0.18, 0, s * 0.62);
    ctx.closePath();
    ctx.fillStyle = "#00D084";
    ctx.fill();

    // Central stem & veins
    ctx.beginPath();
    ctx.moveTo(0, s * 0.74);
    ctx.lineTo(0, -s * 0.56);
    ctx.moveTo(0, s * 0.06);
    ctx.lineTo(-s * 0.24, -s * 0.14);
    ctx.moveTo(0, -s * 0.12);
    ctx.lineTo(s * 0.22, -s * 0.30);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0042);
    ctx.strokeStyle = "#ECFDF5";
    ctx.stroke();

    ctx.restore();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#071410");
  bgGrad.addColorStop(0.52, "#0B221A");
  bgGrad.addColorStop(1, "#103025");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Analytic Loop-Locked Circular Motion & 3-Scene Choreography
  // Base 1 rev + smooth boost 4*0.5 = 3 EXACT revolutions over 20s!
  const baseRev = 1;
  const boostRev = 4;
  const revIntegral = baseRev * cycleNorm + boostRev * (0.5 * cycleNorm - Math.sin(Math.PI * 2 * cycleNorm) / (4 * Math.PI));
  const arrowAngle = revIntegral * Math.PI * 2;
  const gearAngle = -2 * arrowAngle; // Exact -6 revolutions counter-rotation

  let matVis = 0;
  let matRadialFrac = 1;
  let convTrim = 0;
  let convAlpha = 0;
  let leafScale = 0;
  let outerPulseAlpha = 0;

  if (currentScene === 0) {
    // Scene 0: 3 recyclable material nodes orbit calmly then converge smoothly into core
    matVis = 1 - smoothRange(sceneProgress, 0.74, 0.98);
    matRadialFrac = 1 - 0.65 * smoothRange(sceneProgress, 0.30, 0.98);
    convTrim = 0;
    convAlpha = 0;
    leafScale = 0;
    outerPulseAlpha = 0;
  } else if (currentScene === 1) {
    // Scene 1: Peak circular conversion sweep & Eco-Leaf emergence
    matVis = 0;
    matRadialFrac = 0.35;
    convTrim = smoothRange(sceneProgress, 0.05, 0.70);
    convAlpha = smoothRange(sceneProgress, 0.02, 0.20) * (1 - smoothRange(sceneProgress, 0.82, 1.0));
    leafScale = smoothRange(sceneProgress, 0.68, 0.98);
    outerPulseAlpha = smoothRange(sceneProgress, 0.72, 1.0);
  } else {
    // Scene 2: Eco-Leaf showcase with outer confirmation arcs, then clean reset back to material nodes
    if (sceneProgress < 0.72) {
      matVis = 0;
      matRadialFrac = 1;
      leafScale = 1 - smoothRange(sceneProgress, 0.46, 0.72);
    } else {
      matVis = smoothRange(sceneProgress, 0.74, 0.98);
      matRadialFrac = lerp(0.55, 1.0, smoothRange(sceneProgress, 0.74, 0.98));
      leafScale = 0;
    }
    convTrim = 0;
    convAlpha = 0;
    outerPulseAlpha = 1 - smoothRange(sceneProgress, 0.45, 0.75);
  }

  // 3. Layout Coordinates (Strict Concentric Radial Separation)
  const cx = width * 0.5;
  const cy = height * 0.50;

  // Outer Telemetry Ring (r = 0.292 * minSide)
  const outerRingR = minSide * 0.294;
  for (let i = 0; i < 3; i++) {
    const segCenter = -arrowAngle / 3 + (i * Math.PI * 2) / 3;
    const baseSpan = 0.42;
    ctx.beginPath();
    ctx.arc(cx, cy, outerRingR, segCenter - baseSpan, segCenter + baseSpan);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
    ctx.strokeStyle = "#164435";
    ctx.stroke();

    if (outerPulseAlpha > 0.02) {
      ctx.beginPath();
      ctx.arc(cx, cy, outerRingR, segCenter - baseSpan * 0.85, segCenter + baseSpan * 0.85);
      ctx.lineWidth = minSide * 0.0052;
      ctx.strokeStyle = "rgba(0, 208, 132, " + (outerPulseAlpha * 0.88).toFixed(3) + ")";
      ctx.stroke();
    }
  }

  // 4. Three Circular-Economy Ribbon Arrows (r_mid = 0.218 * minSide, thick = 0.044 * minSide -> spans 0.196..0.240)
  const arrowColors = [
    { main: "#00D084", hi: "#6EE7B7" },
    { main: "#00B8D9", hi: "#7DD3FC" },
    { main: "#FBBF24", hi: "#FDE68A" },
  ];
  const midR = minSide * 0.218;
  const ribbonThick = minSide * 0.042;
  const arrowSpan = (Math.PI * 2) / 3 - 0.46; // Generous 26-degree gap between head and next tail!

  for (let i = 0; i < 3; i++) {
    const startA = arrowAngle + (i * Math.PI * 2) / 3 - Math.PI * 0.5;
    const endA = startA + arrowSpan;
    drawCurvedArrow(
      cx,
      cy,
      midR,
      ribbonThick,
      startA,
      endA,
      arrowColors[i].main,
      arrowColors[i].hi,
      0.34
    );
  }

  // 5. Inner Counter-Rotating Precision Gear Ring (r_outer = 0.154 * minSide -> 0.042 * minSide clear of arrows!)
  const gearOuterR = minSide * 0.154;
  const gearInnerR = minSide * 0.132;
  drawGearRing(cx, cy, gearOuterR, gearInnerR, 18, gearAngle, "#183D31", "#94A3B8");

  // 6. Central Conversion Chamber Backdrop (r = 0.112 * minSide -> 0.020 * minSide wall ring inside gear)
  const chamberR = minSide * 0.112;
  ctx.beginPath();
  ctx.arc(cx, cy, chamberR, 0, Math.PI * 2);
  ctx.fillStyle = "#061611";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0055;
  ctx.strokeStyle = "#34D399";
  ctx.stroke();

  // Inner conversion progress ring (r = 0.084 * minSide, cleanly outside leaf & core!)
  if (convAlpha > 0.01 && convTrim > 0.01) {
    const convR = minSide * 0.084;
    ctx.beginPath();
    ctx.arc(cx, cy, convR, 0, Math.PI * 2);
    ctx.lineWidth = minSide * 0.0052;
    ctx.strokeStyle = "rgba(22, 68, 53, " + convAlpha.toFixed(3) + ")";
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(cx, cy, convR, -Math.PI * 0.5, -Math.PI * 0.5 + Math.PI * 2 * convTrim);
    ctx.lineWidth = minSide * 0.0056;
    ctx.strokeStyle = "rgba(0, 208, 132, " + convAlpha.toFixed(3) + ")";
    ctx.stroke();
  }

  // Central Core Hub (visible subtly during conversion transition)
  const corePulse = 0.75 + 0.25 * Math.sin(cycleNorm * Math.PI * 2 * 3);
  if (leafScale < 0.95) {
    const coreVis = 1 - leafScale;
    ctx.beginPath();
    ctx.arc(cx, cy, minSide * 0.016 * corePulse * coreVis, 0, Math.PI * 2);
    ctx.fillStyle = "#34D399";
    ctx.fill();
  }

  // 7. Three Material Input Nodes (Scene 0 & late Scene 2 ONLY — zero overlap with leaf!)
  if (matVis > 0.01) {
    const matOrbitR = minSide * 0.062 * matRadialFrac;
    const matIconR = minSide * 0.025 * matVis;
    const matBaseAngle = cycleNorm * Math.PI * 2 * 1; // Exact 1 revolution over 20s

    for (let m = 0; m < 3; m++) {
      const mAng = matBaseAngle + (m * Math.PI * 2) / 3 - Math.PI * 0.5;
      const mx = cx + Math.cos(mAng) * matOrbitR;
      const my = cy + Math.sin(mAng) * matOrbitR;
      drawMaterialIcon(m, mx, my, matIconR, matVis);
    }
  }

  // 8. Renewed Eco-Leaf Core (Scene 1 tail -> Scene 2)
  if (leafScale > 0.01) {
    const leafBreath = 1 + 0.03 * Math.sin(cycleNorm * Math.PI * 2 * 6);
    drawEcoLeaf(cx, cy + minSide * 0.004, minSide * 0.068 * leafBreath, leafScale);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawGear(gx, gy, outerR, innerR, teeth, angle, fillColor, rimColor, hubColor) {
    ctx.save();
    ctx.translate(gx, gy);
    ctx.rotate(angle);

    ctx.beginPath();
    const step = (Math.PI * 2) / teeth;
    for (let i = 0; i < teeth; i++) {
      const a0 = i * step;
      const a1 = a0 + step * 0.22;
      const a2 = a0 + step * 0.34;
      const a3 = a0 + step * 0.66;
      const a4 = a0 + step * 0.78;
      if (i === 0) ctx.moveTo(Math.cos(a0) * innerR, Math.sin(a0) * innerR);
      else ctx.lineTo(Math.cos(a0) * innerR, Math.sin(a0) * innerR);
      ctx.lineTo(Math.cos(a1) * innerR, Math.sin(a1) * innerR);
      ctx.lineTo(Math.cos(a2) * outerR, Math.sin(a2) * outerR);
      ctx.lineTo(Math.cos(a3) * outerR, Math.sin(a3) * outerR);
      ctx.lineTo(Math.cos(a4) * innerR, Math.sin(a4) * innerR);
    }
    ctx.closePath();
    ctx.fillStyle = fillColor;
    ctx.fill();
    ctx.lineJoin = "round";
    ctx.lineWidth = Math.max(1.2, minSide * 0.0024);
    ctx.strokeStyle = rimColor;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(0, 0, innerR * 0.42, 0, Math.PI * 2);
    ctx.fillStyle = hubColor;
    ctx.fill();

    ctx.restore();
  }

  function drawWindRibbon(x0, x1, yCenter, amp, freq, phase, prog, alpha, color, strokeW) {
    if (alpha <= 0.01) return;
    // Draw sliding smooth segment along x0 -> x1
    const segFrac = 0.56;
    const head = clamp01(prog * (1 + segFrac));
    const tail = clamp01(head - segFrac);
    if (head <= tail + 0.01) return;

    const steps = 28;
    ctx.beginPath();
    for (let s = 0; s <= steps; s++) {
      const u = lerp(tail, head, s / steps);
      const wx = lerp(x0, x1, u);
      const wy = yCenter + Math.sin(u * Math.PI * freq - phase) * amp;
      if (s === 0) ctx.moveTo(wx, wy);
      else ctx.lineTo(wx, wy);
    }
    ctx.lineCap = "round";
    ctx.lineWidth = strokeW;
    ctx.strokeStyle = color;
    ctx.globalAlpha = alpha;
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#09101D");
  bgGrad.addColorStop(0.52, "#101C32");
  bgGrad.addColorStop(1, "#172845");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Analytic Loop-Locked Rotor Kinematics & 3-Scene Choreography
  // Analytic integral of speed(u) = base + boost * (0.5 - 0.5 * cos(2*PI*u)):
  // At u=0 -> 0 rev; at u=1 -> (base + 0.5 * boost) rev = 2 + 6 = 8 EXACT revolutions over 20s!
  const baseRev = 2;
  const boostRev = 12;
  const revIntegral = baseRev * cycleNorm + boostRev * (0.5 * cycleNorm - Math.sin(Math.PI * 2 * cycleNorm) / (4 * Math.PI));
  const bladeAngle = revIntegral * Math.PI * 2;
  const speedNorm = 0.5 - 0.5 * Math.cos(Math.PI * 2 * cycleNorm); // smooth 0 -> 1 -> 0

  let windIntensity = 0.20;
  let powerLevel = 0.22;
  let shaftPulse = 0.25;
  let tipArcAlpha = 0.15;

  if (currentScene === 0) {
    // Scene 0: Inflow wind surges from left, turbine accelerates, power begins climbing
    windIntensity = 0.20 + 0.80 * smoothRange(sceneProgress, 0.05, 0.90);
    powerLevel = 0.22 + 0.42 * smoothRange(sceneProgress, 0.20, 0.96);
    shaftPulse = 0.25 + 0.65 * smoothRange(sceneProgress, 0.15, 0.95);
    tipArcAlpha = 0.15 + 0.65 * smoothRange(sceneProgress, 0.25, 0.95);
  } else if (currentScene === 1) {
    // Scene 1: Peak aero-dynamo generation, full 5-level meter & active outflow streams
    windIntensity = 1.0 - 0.15 * smoothRange(sceneProgress, 0.80, 1.0);
    powerLevel = 0.64 + 0.36 * smoothRange(sceneProgress, 0.0, 0.65);
    shaftPulse = 0.90 + 0.10 * Math.sin(Math.PI * sceneProgress);
    tipArcAlpha = 0.80 + 0.20 * Math.sin(Math.PI * sceneProgress);
  } else {
    // Scene 2: Controlled wind tapering & smooth power dissipation back to seamless baseline
    windIntensity = 0.85 - 0.65 * smoothRange(sceneProgress, 0.12, 0.92);
    powerLevel = 1.0 - 0.78 * smoothRange(sceneProgress, 0.18, 0.94);
    shaftPulse = 0.90 - 0.65 * smoothRange(sceneProgress, 0.15, 0.92);
    tipArcAlpha = 0.80 - 0.65 * smoothRange(sceneProgress, 0.10, 0.90);
  }

  // 3. Layout Coordinates (Balanced 16:9 margins, strict non-overlapping zones)
  const cx = width * 0.5;
  const cy = height * 0.50;

  const hubX = cx;
  const hubY = cy - minSide * 0.085;
  const bladeLen = minSide * 0.232; // Sweep bottom at cy + 0.147 * minSide

  const pedTop = cy + minSide * 0.205; // 0.058 * minSide clearance below lowest blade tip!
  const pedH = minSide * 0.132;
  const pedW = minSide * 0.370;
  const pedLeft = cx - pedW * 0.5;
  const pedR = minSide * 0.024;

  // 4. Outer Aerodynamic Wind Ribbons (Strictly outside rotor sweep circle + margin!)
  const leftStart = cx - minSide * 0.450;
  const leftEnd = cx - minSide * 0.278; // 0.046 * minSide clear of blade radius (0.232)
  const rightStart = cx + minSide * 0.278;
  const rightEnd = cx + minSide * 0.450;

  const windPhase = cycleNorm * Math.PI * 2 * 6;
  const streamRows = [
    { yOff: -0.105, phase: 0.0, color: "#38BDF8" },
    { yOff: 0.0, phase: 0.33, color: "#4BFFB8" },
    { yOff: 0.105, phase: 0.66, color: "#38BDF8" },
  ];

  for (let i = 0; i < streamRows.length; i++) {
    const r = streamRows[i];
    const pIn = (cycleNorm * 5 + r.phase) % 1;
    const pOut = (cycleNorm * 5 + r.phase + 0.22) % 1;
    const wAmp = minSide * 0.0085 * (0.4 + 0.6 * windIntensity);
    const wAlphaIn = Math.sin(Math.PI * pIn) * windIntensity * 0.88;
    const wAlphaOut = Math.sin(Math.PI * pOut) * windIntensity * 0.82;

    drawWindRibbon(
      leftStart,
      leftEnd,
      hubY + r.yOff * minSide,
      wAmp,
      2.2,
      windPhase,
      pIn,
      wAlphaIn,
      r.color,
      Math.max(1.8, minSide * 0.0044)
    );
    drawWindRibbon(
      rightStart,
      rightEnd,
      hubY + r.yOff * minSide,
      wAmp,
      2.2,
      windPhase,
      pOut,
      wAlphaOut,
      r.color,
      Math.max(1.8, minSide * 0.0042)
    );
  }

  // 5. Sleek Tapered Tower Mast & Internal Conduit Shaft (Rigid, architectural, zero distortion)
  const mastTopW = minSide * 0.022;
  const mastBotW = minSide * 0.044;

  // Left lighter facet + Right shaded periwinkle facet (clean 2-tone flat vector)
  ctx.beginPath();
  ctx.moveTo(cx - mastTopW * 0.5, hubY);
  ctx.lineTo(cx, hubY);
  ctx.lineTo(cx, pedTop + minSide * 0.006);
  ctx.lineTo(cx - mastBotW * 0.5, pedTop + minSide * 0.006);
  ctx.closePath();
  ctx.fillStyle = "#F4F7FB";
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(cx, hubY);
  ctx.lineTo(cx + mastTopW * 0.5, hubY);
  ctx.lineTo(cx + mastBotW * 0.5, pedTop + minSide * 0.006);
  ctx.lineTo(cx, pedTop + minSide * 0.006);
  ctx.closePath();
  ctx.fillStyle = "#B8C7E8";
  ctx.fill();

  // Internal Energy Conduit Channel running straight down center of tower cleanly into pedestal
  const chanTop = hubY + minSide * 0.032;
  const chanBot = pedTop + minSide * 0.002;
  ctx.beginPath();
  ctx.moveTo(cx, chanTop);
  ctx.lineTo(cx, chanBot);
  ctx.lineCap = "round";
  ctx.lineWidth = minSide * 0.007;
  ctx.strokeStyle = "#1B2E52";
  ctx.stroke();

  // Descending crisp energy packet pills inside tower conduit
  if (shaftPulse > 0.05) {
    for (let k = 0; k < 2; k++) {
      const kProg = (cycleNorm * 6 + k * 0.5) % 1;
      const py = lerp(chanTop + minSide * 0.012, chanBot - minSide * 0.012, kProg);
      const pAlpha = Math.sin(Math.PI * kProg) * shaftPulse;
      if (pAlpha > 0.04) {
        ctx.beginPath();
        ctx.moveTo(cx, py - minSide * 0.009);
        ctx.lineTo(cx, py + minSide * 0.009);
        ctx.lineCap = "round";
        ctx.lineWidth = minSide * 0.0046;
        ctx.strokeStyle = "rgba(75, 255, 184, " + pAlpha.toFixed(3) + ")";
        ctx.stroke();
      }
    }
  }

  // 6. Outer Blade-Tip Aerodynamic Arcs (Strictly outside blade radius + 0.022 * minSide)
  if (tipArcAlpha > 0.02) {
    const arcR = bladeLen + minSide * 0.022;
    const arcLen = 0.28 * (0.65 + 0.35 * speedNorm);
    for (let b = 0; b < 3; b++) {
      const tipAng = bladeAngle + (b * Math.PI * 2) / 3 - Math.PI * 0.5;
      ctx.beginPath();
      ctx.arc(hubX, hubY, arcR, tipAng - arcLen, tipAng - 0.04);
      ctx.lineCap = "round";
      ctx.lineWidth = Math.max(1.5, minSide * 0.0036);
      ctx.strokeStyle = "rgba(75, 255, 184, " + (tipArcAlpha * 0.72).toFixed(3) + ")";
      ctx.stroke();
    }
  }

  // 7. Aerodynamic 3-Blade Rotor & Center Hub
  for (let b = 0; b < 3; b++) {
    const bAng = bladeAngle + (b * Math.PI * 2) / 3 - Math.PI * 0.5;
    ctx.save();
    ctx.translate(hubX, hubY);
    ctx.rotate(bAng);

    // Blade length along +x from hub radius out to bladeLen
    const rootX = minSide * 0.020;
    const midX = bladeLen * 0.32;
    const tipX = bladeLen;
    const maxHalfW = minSide * 0.021;
    const tipHalfW = minSide * 0.0055;

    // Leading-edge bright ivory half
    ctx.beginPath();
    ctx.moveTo(rootX, 0);
    ctx.lineTo(rootX + minSide * 0.012, -maxHalfW * 0.68);
    ctx.quadraticCurveTo(midX, -maxHalfW, tipX, -tipHalfW);
    ctx.quadraticCurveTo(tipX + minSide * 0.005, 0, tipX, 0);
    ctx.closePath();
    ctx.fillStyle = "#F4F7FB";
    ctx.fill();

    // Trailing-edge periwinkle shaded half
    ctx.beginPath();
    ctx.moveTo(rootX, 0);
    ctx.lineTo(tipX, 0);
    ctx.quadraticCurveTo(tipX + minSide * 0.005, 0, tipX, tipHalfW);
    ctx.quadraticCurveTo(midX, maxHalfW * 0.52, rootX + minSide * 0.012, maxHalfW * 0.45);
    ctx.closePath();
    ctx.fillStyle = "#8BA6FF";
    ctx.fill();

    // Crisp mint aerodynamic tip accent band
    ctx.beginPath();
    ctx.moveTo(tipX - minSide * 0.026, -tipHalfW * 1.45);
    ctx.lineTo(tipX, -tipHalfW);
    ctx.quadraticCurveTo(tipX + minSide * 0.005, 0, tipX, tipHalfW);
    ctx.lineTo(tipX - minSide * 0.026, tipHalfW * 1.35);
    ctx.closePath();
    ctx.fillStyle = "#4BFFB8";
    ctx.fill();

    ctx.restore();
  }

  // Rotor Center Spinner Hub
  ctx.beginPath();
  ctx.arc(hubX, hubY, minSide * 0.028, 0, Math.PI * 2);
  ctx.fillStyle = "#162A4D";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0055;
  ctx.strokeStyle = "#F4F7FB";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(hubX, hubY, minSide * 0.012, 0, Math.PI * 2);
  ctx.fillStyle = "#4BFFB8";
  ctx.fill();

  // 8. Base Dynamo Generator Pedestal (Gear Cutaway Window + Left/Right Power Meter Banks)
  roundedRectPath(pedLeft, pedTop, pedW, pedH, pedR);
  ctx.fillStyle = "#132340";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0058;
  ctx.strokeStyle = "#7C9CFF";
  ctx.stroke();

  // Recessed Center Gear Cutaway Viewport
  const winW = minSide * 0.138;
  const winH = minSide * 0.088;
  const winX = cx - winW * 0.5;
  const winY = pedTop + (pedH - winH) * 0.5;
  const winR = minSide * 0.016;

  roundedRectPath(winX, winY, winW, winH, winR);
  ctx.fillStyle = "#091326";
  ctx.fill();

  ctx.save();
  roundedRectPath(winX, winY, winW, winH, winR);
  ctx.clip();

  // Precision 12-tooth primary gear + 8-tooth pinion meshing cleanly inside viewport
  // Pitch radii: R1 = 0.026, R2 = 0.01733 -> center distance = 0.04333 + tooth clearance
  const g1R_outer = minSide * 0.030;
  const g1R_inner = minSide * 0.0225;
  const g2R_outer = minSide * 0.022;
  const g2R_inner = minSide * 0.0145;
  const centerDist = minSide * 0.045;
  const gearY = winY + winH * 0.5;
  const g1X = cx - centerDist * 0.42;
  const g2X = g1X + centerDist;

  // Gear 1 (12 teeth) rotates at bladeAngle; Gear 2 (8 teeth) rotates at -1.5 * bladeAngle + tooth phase offset
  const g1Angle = bladeAngle;
  const g2Angle = -1.5 * bladeAngle + Math.PI / 8;

  drawGear(g1X, gearY, g1R_outer, g1R_inner, 12, g1Angle, "#38BDF8", "#BAE6FD", "#091326");
  drawGear(g2X, gearY, g2R_outer, g2R_inner, 8, g2Angle, "#4BFFB8", "#D1FAE5", "#091326");

  ctx.restore();

  // Crisp viewport frame on top
  roundedRectPath(winX, winY, winW, winH, winR);
  ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
  ctx.strokeStyle = "#3B598E";
  ctx.stroke();

  // Symmetrical Left & Right 4-Bar Output Power Meters inside Pedestal (Clean gap from gear viewport!)
  const barCount = 4;
  const barW = minSide * 0.013;
  const barGap = minSide * 0.008;
  const maxBarH = minSide * 0.072;
  const barBaseY = pedTop + pedH - (pedH - maxBarH) * 0.5;

  for (let side = -1; side <= 1; side += 2) {
    for (let b = 0; b < barCount; b++) {
      // Inner-to-outer growth symmetrically
      const barIdx = b;
      const distFromViewport = minSide * 0.024 + barIdx * (barW + barGap);
      const bx = side === 1 ? winX + winW + distFromViewport : winX - distFromViewport - barW;
      const targetH = maxBarH * (0.42 + 0.58 * ((barIdx + 1) / barCount));

      // Background unlit track bar
      roundedRectPath(bx, barBaseY - targetH, barW, targetH, barW * 0.4);
      ctx.fillStyle = "#0B172E";
      ctx.fill();

      // Active fill threshold
      const segThresh = barIdx / barCount;
      const barFill = clamp01((powerLevel - segThresh) * barCount);
      if (barFill > 0.02) {
        const activeH = targetH * barFill;
        roundedRectPath(bx, barBaseY - activeH, barW, activeH, barW * 0.4);
        ctx.fillStyle = barIdx >= 2 ? "#4BFFB8" : "#38BDF8";
        ctx.fill();
      }
    }
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function lerp3Color(c0, c1, c2, k) {
    const tK = clamp01(k);
    if (tK <= 0.5) return lerpColor(c0, c1, tK * 2);
    return lerpColor(c1, c2, (tK - 0.5) * 2);
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function traceThermometerPath(cx, stemTop, halfStem, bulbY, bulbR) {
    const capCy = stemTop + halfStem;
    const joinSin = clamp01(halfStem / bulbR);
    const joinAlpha = Math.asin(joinSin);
    const startAngle = -Math.PI * 0.5 + joinAlpha;
    const endAngle = Math.PI * 1.5 - joinAlpha;

    ctx.beginPath();
    ctx.arc(cx, capCy, halfStem, Math.PI, 0, false);
    ctx.arc(cx, bulbY, bulbR, startAngle, endAngle, false);
    ctx.closePath();
  }

  function drawCrystal(x, y, r, rot, alpha, color) {
    if (alpha <= 0.02 || r <= 0.5) return;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = color;
    ctx.lineCap = "round";
    ctx.lineWidth = Math.max(1.2, minSide * 0.0028);

    for (let i = 0; i < 3; i++) {
      const a = (i * Math.PI) / 3;
      const dx = Math.cos(a) * r;
      const dy = Math.sin(a) * r;
      ctx.beginPath();
      ctx.moveTo(-dx, -dy);
      ctx.lineTo(dx, dy);
      ctx.stroke();
    }

    ctx.beginPath();
    ctx.arc(0, 0, r * 0.28, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  }

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#120916");
  bgGrad.addColorStop(0.52, "#1B0E23");
  bgGrad.addColorStop(1, "#271330");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  // heatNorm: 0 = cool Mint Equilibrium, 1 = high Crimson Thermal Spike
  let heatNorm = 0.45;
  let coolActive = 0;
  let badgeMode = 0; // 0 = heat wave monitor, 1 = stable equilibrium check

  if (currentScene === 0) {
    // Scene 0: Thermal surge climbs smoothly from baseline 0.45 -> 0.94
    heatNorm = 0.45 + 0.49 * easeInOutSine(sceneProgress);
    coolActive = 0;
    badgeMode = 0;
  } else if (currentScene === 1) {
    // Scene 1: Atmospheric cooling winds & crystals activate, stabilizing temperature 0.94 -> 0.16
    heatNorm = 0.94 - 0.78 * smoothRange(sceneProgress, 0.10, 0.92);
    coolActive = Math.sin(Math.PI * clamp01((sceneProgress - 0.02) / 0.96));
    badgeMode = smoothRange(sceneProgress, 0.72, 1.0) * 0.35;
  } else {
    // Scene 2: Equilibrium lock + clean badge checkmark, then smooth seamless return 0.16 -> 0.45
    coolActive = 0;
    if (sceneProgress < 0.58) {
      heatNorm = 0.16;
      badgeMode = 0.35 + 0.65 * smoothRange(sceneProgress, 0.0, 0.28);
    } else {
      heatNorm = 0.16 + 0.29 * smoothRange(sceneProgress, 0.58, 0.96);
      badgeMode = 1 - smoothRange(sceneProgress, 0.58, 0.88);
    }
  }

  const wavePhase = cycleNorm * Math.PI * 2 * 6;
  const mercuryLevel = lerp(0.26, 0.88, heatNorm);

  // Interpolated 3-stop vibrant thermal color palettes (Mint -> Solar Amber -> Crimson, zero muddy grey)
  const topLiquidColor = lerp3Color([56, 242, 198], [255, 184, 48], [255, 61, 90], heatNorm);
  const midLiquidColor = lerp3Color([56, 189, 248], [249, 115, 22], [244, 63, 94], heatNorm);
  const baseLiquidColor = lerp3Color([13, 148, 136], [217, 119, 6], [190, 18, 60], heatNorm);
  const continentColor = lerp3Color([52, 211, 153], [251, 191, 36], [251, 113, 133], heatNorm);
  const oceanTopColor = lerp3Color([14, 72, 108], [32, 34, 78], [58, 22, 54], heatNorm);
  const oceanBotColor = lerp3Color([9, 44, 74], [21, 20, 52], [36, 14, 38], heatNorm);

  // 3. Balanced 16:9 Layout Coordinates
  const cx = width * 0.5;
  const cy = height * 0.52;

  const stemTop = cy - minSide * 0.275;
  const halfStem = minSide * 0.042;
  const bulbY = cy + minSide * 0.145;
  const bulbR = minSide * 0.115;

  // 4. Flanking Atmospheric Cooling Arcs Around Globe Bulb (Strictly below stem join, clear of dials!)
  if (coolActive > 0.01) {
    const coolRing1 = bulbR + minSide * 0.024;
    const coolRing2 = bulbR + minSide * 0.042;

    for (let side = -1; side <= 1; side += 2) {
      const baseMid = side === 1 ? 0.08 * Math.PI : 0.92 * Math.PI;
      const span = 0.26 * Math.PI * coolActive;
      const shift = Math.sin(cycleNorm * Math.PI * 2 * 3) * 0.06;

      ctx.beginPath();
      ctx.arc(cx, bulbY, coolRing1, baseMid - span + shift * side, baseMid + span + shift * side);
      ctx.lineCap = "round";
      ctx.lineWidth = Math.max(1.8, minSide * 0.0042);
      ctx.strokeStyle = "rgba(86, 204, 242, " + (coolActive * 0.85).toFixed(3) + ")";
      ctx.stroke();

      const span2 = 0.19 * Math.PI * coolActive;
      ctx.beginPath();
      ctx.arc(cx, bulbY, coolRing2, baseMid - span2 - shift * side, baseMid + span2 - shift * side);
      ctx.lineCap = "round";
      ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
      ctx.strokeStyle = "rgba(56, 242, 198, " + (coolActive * 0.65).toFixed(3) + ")";
      ctx.stroke();
    }

    // Symmetrical Geometric Frost Crystals in Clear Corridor Lanes (|dx| = 0.128 * minSide)
    const crystalLanes = [
      { xOff: -0.128, phase: 0.0, r: 0.012 },
      { xOff: 0.128, phase: 0.0, r: 0.012 },
      { xOff: -0.128, phase: 0.5, r: 0.0095 },
      { xOff: 0.128, phase: 0.5, r: 0.0095 },
    ];
    const crysTop = cy - minSide * 0.22;
    const crysBot = cy - minSide * 0.02;

    for (let i = 0; i < crystalLanes.length; i++) {
      const c = crystalLanes[i];
      const prog = (cycleNorm * 4 + c.phase) % 1;
      const alpha = Math.sin(Math.PI * prog) * coolActive * 0.88;
      const cyPos = lerp(crysTop, crysBot, prog);
      const cxPos = cx + c.xOff * minSide;
      const rot = prog * Math.PI * 0.5 * (c.xOff > 0 ? 1 : -1);
      drawCrystal(cxPos, cyPos, minSide * c.r, rot, alpha, "#7CE8FF");
    }
  }

  // 5. Thermometer Glass Chamber (Single Continuous Seamless Vector Silhouette)
  const wallPad = minSide * 0.014;
  const inHalfStem = halfStem - wallPad;
  const inBulbR = bulbR - wallPad;
  const inStemTop = stemTop + wallPad;

  // Dark housing backdrop
  traceThermometerPath(cx, stemTop, halfStem, bulbY, bulbR);
  ctx.fillStyle = "#140A1C";
  ctx.fill();

  // Clipped interior
  ctx.save();
  traceThermometerPath(cx, inStemTop, inHalfStem, bulbY, inBulbR);
  ctx.clip();

  // Inner chamber dark glass fill + crisp flat-vector right shadow band
  ctx.fillStyle = "#0D0614";
  ctx.fillRect(cx - bulbR, stemTop, bulbR * 2, bulbY + bulbR - stemTop);
  ctx.fillStyle = "#09040E";
  ctx.fillRect(cx + inHalfStem * 0.35, stemTop, bulbR, bulbY - stemTop);

  // --- STEM THERMAL LIQUID COLUMN ---
  const tubeJoinY = bulbY - Math.sqrt(Math.max(0, inBulbR * inBulbR - inHalfStem * inHalfStem));
  const tubeTopLimit = inStemTop + inHalfStem * 0.9;
  const tubeBotBase = tubeJoinY + minSide * 0.015;
  const tubeSpan = tubeBotBase - tubeTopLimit;
  const mercuryY = tubeBotBase - tubeSpan * mercuryLevel;
  const waveAmp = minSide * 0.0036;

  ctx.beginPath();
  ctx.moveTo(cx - inHalfStem, tubeBotBase);
  const mSteps = 20;
  for (let s = 0; s <= mSteps; s++) {
    const u = s / mSteps;
    const wx = cx - inHalfStem + u * inHalfStem * 2;
    const wy = mercuryY + Math.sin(u * Math.PI * 2 + wavePhase) * waveAmp;
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(cx + inHalfStem, tubeBotBase);
  ctx.closePath();

  const colGrad = ctx.createLinearGradient(cx, mercuryY, cx, tubeBotBase);
  colGrad.addColorStop(0, topLiquidColor);
  colGrad.addColorStop(0.5, midLiquidColor);
  colGrad.addColorStop(1, baseLiquidColor);
  ctx.fillStyle = colGrad;
  ctx.fill();

  // Crisp meniscus highlight on mercury surface
  ctx.beginPath();
  for (let s = 0; s <= mSteps; s++) {
    const u = s / mSteps;
    const wx = cx - inHalfStem + u * inHalfStem * 2;
    const wy = mercuryY + Math.sin(u * Math.PI * 2 + wavePhase) * waveAmp;
    if (s === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.lineWidth = Math.max(1.2, minSide * 0.0024);
  ctx.strokeStyle = "rgba(255, 255, 255, 0.72)";
  ctx.stroke();

  // Subtle internal rising micro-bubbles inside fluid column
  const colSpan = tubeBotBase - (mercuryY + minSide * 0.016);
  if (colSpan > minSide * 0.025) {
    const bubs = [
      { xOff: -0.010, speed: 3, phase: 0.15, r: 0.0032 },
      { xOff: 0.009, speed: 4, phase: 0.62, r: 0.0026 },
    ];
    for (let i = 0; i < bubs.length; i++) {
      const b = bubs[i];
      const prog = (cycleNorm * b.speed + b.phase) % 1;
      const by = lerp(tubeBotBase - minSide * 0.014, mercuryY + minSide * 0.014, prog);
      const bx = cx + b.xOff * minSide;
      const bAlpha = Math.sin(Math.PI * prog) * 0.6;
      if (bAlpha > 0.03) {
        ctx.beginPath();
        ctx.arc(bx, by, minSide * b.r, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(255, 255, 255, " + bAlpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // --- GLOBE BULB AT BASE (Cleanly framed circular world inside bulb) ---
  const globeR = inBulbR * 0.88;
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, bulbY, globeR, 0, Math.PI * 2);
  ctx.clip();

  const oceanGrad = ctx.createLinearGradient(cx, bulbY - globeR, cx, bulbY + globeR);
  oceanGrad.addColorStop(0, oceanTopColor);
  oceanGrad.addColorStop(1, oceanBotColor);
  ctx.fillStyle = oceanGrad;
  ctx.fillRect(cx - globeR, bulbY - globeR, globeR * 2, globeR * 2);

  // Seamlessly rotating flat-vector geometric continents (period = 2 * globeR * 2 over 20s)
  const wrapWidth = globeR * 2.6;
  const scrollX = (cycleNorm * wrapWidth) % wrapWidth;

  ctx.fillStyle = continentColor;
  for (let rep = -1; rep <= 1; rep++) {
    const ox = cx - globeR + scrollX + rep * wrapWidth;

    // Continent landmass 1 (northern rounded capsule cluster)
    roundedRectPath(ox + globeR * 0.15, bulbY - globeR * 0.56, globeR * 0.72, globeR * 0.34, globeR * 0.17);
    ctx.fill();
    roundedRectPath(ox + globeR * 0.42, bulbY - globeR * 0.28, globeR * 0.48, globeR * 0.28, globeR * 0.14);
    ctx.fill();

    // Continent landmass 2 (southern geometric landmass)
    roundedRectPath(ox + globeR * 1.15, bulbY + globeR * 0.06, globeR * 0.82, globeR * 0.38, globeR * 0.19);
    ctx.fill();
    roundedRectPath(ox + globeR * 1.38, bulbY - globeR * 0.42, globeR * 0.54, globeR * 0.26, globeR * 0.13);
    ctx.fill();
  }

  // Flat-vector subtle crescent shading on right side of globe
  ctx.beginPath();
  ctx.arc(cx, bulbY, globeR, -Math.PI * 0.4, Math.PI * 0.55);
  ctx.lineWidth = globeR * 0.24;
  ctx.strokeStyle = "rgba(8, 4, 14, 0.28)";
  ctx.stroke();

  ctx.restore();

  // Crisp inner ring separating globe emblem cleanly from outer glass rim
  ctx.beginPath();
  ctx.arc(cx, bulbY, globeR, 0, Math.PI * 2);
  ctx.lineWidth = Math.max(1.5, minSide * 0.0036);
  ctx.strokeStyle = "rgba(243, 232, 255, 0.45)";
  ctx.stroke();

  // Subtle vertical specular highlight inside stem left wall
  ctx.beginPath();
  ctx.moveTo(cx - inHalfStem * 0.62, inStemTop + inHalfStem * 1.1);
  ctx.lineTo(cx - inHalfStem * 0.62, tubeJoinY - minSide * 0.015);
  ctx.lineCap = "round";
  ctx.lineWidth = Math.max(1.5, minSide * 0.0045);
  ctx.strokeStyle = "rgba(243, 232, 255, 0.24)";
  ctx.stroke();

  ctx.restore();

  // Outer Thermometer Glass Border
  traceThermometerPath(cx, stemTop, halfStem, bulbY, bulbR);
  ctx.lineWidth = minSide * 0.0072;
  ctx.strokeStyle = "#F3E8FF";
  ctx.stroke();

  // 6. Clean Left Graduation Scale Ticks (Strictly outside left stem wall, above bulb)
  const tickCount = 6;
  const tickTop = inStemTop + inHalfStem * 1.1;
  const tickBot = bulbY - bulbR - minSide * 0.022;
  const tickXRight = cx - halfStem - minSide * 0.014;

  for (let i = 0; i < tickCount; i++) {
    const ty = lerp(tickTop, tickBot, i / (tickCount - 1));
    const isMajor = i % 2 === 0;
    const tLen = minSide * (isMajor ? 0.020 : 0.011);
    ctx.beginPath();
    ctx.moveTo(tickXRight - tLen, ty);
    ctx.lineTo(tickXRight, ty);
    ctx.lineCap = "round";
    ctx.lineWidth = Math.max(1.5, minSide * 0.003);
    ctx.strokeStyle = isMajor ? "#E9D5FF" : "#7E5B99";
    ctx.stroke();
  }

  // 7. Left Analog Thermal Balance Dial (Clearance >= 0.11 * minSide from stem ticks)
  const dialX = cx - minSide * 0.248;
  const dialY = cy - minSide * 0.02;
  const dialR = minSide * 0.062;

  ctx.beginPath();
  ctx.arc(dialX, dialY, dialR, 0, Math.PI * 2);
  ctx.fillStyle = "#190D24";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0048;
  ctx.strokeStyle = "#5B3B78";
  ctx.stroke();

  // 3-zone color arc: Left = Cool Mint, Center = Balanced Sky, Right = Hot Crimson
  const arcR = dialR * 0.72;
  const arcW = minSide * 0.0068;
  const aStart = Math.PI * 0.85;
  const aMid1 = Math.PI * 1.28;
  const aMid2 = Math.PI * 1.72;
  const aEnd = Math.PI * 2.15;

  ctx.lineCap = "round";
  ctx.lineWidth = arcW;

  ctx.beginPath();
  ctx.arc(dialX, dialY, arcR, aStart, aMid1 - 0.06);
  ctx.strokeStyle = "#38F2C6";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(dialX, dialY, arcR, aMid1 + 0.06, aMid2 - 0.06);
  ctx.strokeStyle = "#FF914D";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(dialX, dialY, arcR, aMid2 + 0.06, aEnd);
  ctx.strokeStyle = "#FF3D5A";
  ctx.stroke();

  // Smoothly rotating analog needle mapped directly to heatNorm (0 -> mint left-up, 1 -> crimson right)
  const needleAngle = lerp(Math.PI * 1.10, Math.PI * 2.02, heatNorm);
  const needleLen = dialR * 0.62;
  ctx.beginPath();
  ctx.moveTo(dialX, dialY);
  ctx.lineTo(dialX + Math.cos(needleAngle) * needleLen, dialY + Math.sin(needleAngle) * needleLen);
  ctx.lineCap = "round";
  ctx.lineWidth = minSide * 0.0046;
  ctx.strokeStyle = "#F3E8FF";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(dialX, dialY, minSide * 0.0075, 0, Math.PI * 2);
  ctx.fillStyle = topLiquidColor;
  ctx.fill();

  // 8. Right Reactive Thermal Status Badge (Clearance >= 0.068 * minSide from globe)
  const badgeX = cx + minSide * 0.248;
  const badgeY = cy - minSide * 0.02;
  const badgeR = minSide * 0.062;
  const badgeRingColor = lerp3Color([56, 242, 198], [255, 184, 48], [255, 61, 90], heatNorm);

  ctx.beginPath();
  ctx.arc(badgeX, badgeY, badgeR, 0, Math.PI * 2);
  ctx.fillStyle = "#190D24";
  ctx.fill();

  ctx.beginPath();
  ctx.arc(badgeX, badgeY, badgeR - minSide * 0.007, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.0072;
  ctx.strokeStyle = "#331D47";
  ctx.stroke();

  // Active status arc
  const badgeFill = lerp(1.0, 0.35, heatNorm);
  ctx.beginPath();
  ctx.arc(badgeX, badgeY, badgeR - minSide * 0.007, -Math.PI * 0.5, -Math.PI * 0.5 + Math.PI * 2 * badgeFill);
  ctx.lineCap = "round";
  ctx.lineWidth = minSide * 0.0072;
  ctx.strokeStyle = badgeRingColor;
  ctx.stroke();

  // Clean non-overlapping crossfade between thermal wave indicator (badgeMode <= 0.35) and equilibrium check (badgeMode >= 0.35)
  const waveVis = 1 - smoothRange(badgeMode, 0.0, 0.34);
  if (waveVis > 0.01) {
    ctx.save();
    ctx.globalAlpha = waveVis;
    ctx.strokeStyle = badgeRingColor;
    ctx.lineCap = "round";
    ctx.lineWidth = minSide * 0.0052;
    const wSpan = badgeR * 0.44;
    for (let row = -1; row <= 1; row += 2) {
      ctx.beginPath();
      for (let s = 0; s <= 14; s++) {
        const u = s / 14;
        const wx = badgeX - wSpan + u * wSpan * 2;
        const wy = badgeY + row * badgeR * 0.16 + Math.sin(u * Math.PI * 2 + wavePhase) * minSide * 0.0045;
        if (s === 0) ctx.moveTo(wx, wy);
        else ctx.lineTo(wx, wy);
      }
      ctx.stroke();
    }
    ctx.restore();
  }

  const checkVis = smoothRange(badgeMode, 0.36, 1.0);
  if (checkVis > 0.01) {
    const p0x = badgeX - badgeR * 0.32;
    const p0y = badgeY + badgeR * 0.03;
    const p1x = badgeX - badgeR * 0.05;
    const p1y = badgeY + badgeR * 0.27;
    const p2x = badgeX + badgeR * 0.36;
    const p2y = badgeY - badgeR * 0.23;

    const seg1 = clamp01(checkVis / 0.42);
    const seg2 = clamp01((checkVis - 0.42) / 0.58);

    ctx.beginPath();
    ctx.moveTo(p0x, p0y);
    ctx.lineTo(lerp(p0x, p1x, seg1), lerp(p0y, p1y, seg1));
    if (seg2 > 0) {
      ctx.lineTo(lerp(p1x, p2x, seg2), lerp(p1y, p2y, seg2));
    }
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.lineWidth = minSide * 0.0074;
    ctx.strokeStyle = "#38F2C6";
    ctx.stroke();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutCubic(x) {
    return 1 - Math.pow(1 - x, 3);
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function traceTeardropPath(cx, topY, botY, neckHalfW, bellyHalfW, bellyY) {
    const h = botY - topY;
    ctx.beginPath();
    ctx.moveTo(cx - neckHalfW, topY);
    ctx.lineTo(cx + neckHalfW, topY);
    ctx.bezierCurveTo(
      cx + neckHalfW + minSide * 0.012,
      topY + h * 0.16,
      cx + bellyHalfW,
      bellyY - h * 0.18,
      cx + bellyHalfW,
      bellyY
    );
    ctx.bezierCurveTo(
      cx + bellyHalfW,
      bellyY + h * 0.21,
      cx + bellyHalfW * 0.54,
      botY,
      cx,
      botY
    );
    ctx.bezierCurveTo(
      cx - bellyHalfW * 0.54,
      botY,
      cx - bellyHalfW,
      bellyY + h * 0.21,
      cx - bellyHalfW,
      bellyY
    );
    ctx.bezierCurveTo(
      cx - bellyHalfW,
      bellyY - h * 0.18,
      cx - neckHalfW - minSide * 0.012,
      topY + h * 0.16,
      cx - neckHalfW,
      topY
    );
    ctx.closePath();
  }

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#050B1E");
  bgGrad.addColorStop(0.55, "#091736");
  bgGrad.addColorStop(1, "#0F2452");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let pourRate = 0;
  let pourReach = 0;
  let upperLevel = 0.0;
  let lowerLevel = 0.14;
  let filterFlow = 0;
  let purityScore = 0;
  let checkTrim = 0;
  let valveOpen = 0;
  let rippleStrength = 0;

  if (currentScene === 0) {
    // Scene 0: Impure water smoothly streams in from top collar and fills upper chamber cleanly from 0 -> 0.86
    const rampIn = smoothRange(sceneProgress, 0.03, 0.20);
    const rampOut = 1 - smoothRange(sceneProgress, 0.74, 0.96);
    pourRate = Math.min(rampIn, rampOut);
    pourReach = easeOutCubic(clamp01((sceneProgress - 0.03) / 0.14));
    upperLevel = 0.86 * smoothRange(sceneProgress, 0.12, 0.95);
    lowerLevel = 0.14;
    filterFlow = 0;
    purityScore = 0;
    checkTrim = 0;
    valveOpen = 0;
    rippleStrength = 0;
  } else if (currentScene === 1) {
    // Scene 1: Active membrane filtration drains upper chamber cleanly to 0 while purified pool rises 0.14 -> 0.88
    pourRate = 0;
    pourReach = 0;
    upperLevel = 0.86 * (1 - smoothRange(sceneProgress, 0.04, 0.88));
    lowerLevel = 0.14 + 0.74 * smoothRange(sceneProgress, 0.10, 0.94);
    filterFlow = Math.sin(Math.PI * clamp01((sceneProgress - 0.04) / 0.88));
    purityScore = smoothRange(sceneProgress, 0.14, 0.92);
    checkTrim = 0;
    valveOpen = 0;
    rippleStrength = smoothRange(sceneProgress, 0.76, 1.0);
  } else {
    // Scene 2: Pure optimal status lock, clean flanking ripples, controlled outlet drain back to 0.14
    pourRate = 0;
    pourReach = 0;
    upperLevel = 0.0;
    lowerLevel = 0.88 - 0.74 * smoothRange(sceneProgress, 0.20, 0.94);
    filterFlow = 0;
    purityScore = 1 - smoothRange(sceneProgress, 0.64, 0.98);
    if (sceneProgress < 0.62) {
      checkTrim = smoothRange(sceneProgress, 0.0, 0.30);
    } else {
      checkTrim = 1 - smoothRange(sceneProgress, 0.62, 0.86);
    }
    valveOpen = Math.sin(Math.PI * clamp01((sceneProgress - 0.16) / 0.80));
    rippleStrength = 1 - smoothRange(sceneProgress, 0.48, 0.88);
  }

  // Exact integer harmonics across 20s for seamless looping
  const wavePhase1 = cycleNorm * Math.PI * 2 * 6;
  const wavePhase2 = cycleNorm * Math.PI * 2 * 9;

  // 3. Layout Coordinates (Balanced 16:9 alignment, strict non-overlapping clearances)
  const cx = width * 0.5;
  const cy = height * 0.54;

  const dropX = cx - minSide * 0.035;
  const dropTop = cy - minSide * 0.22;
  const dropBot = cy + minSide * 0.24;
  const dropH = dropBot - dropTop;
  const neckHalfW = minSide * 0.036;
  const bellyHalfW = minSide * 0.165;
  const bellyY = dropTop + dropH * 0.62;

  const filterY = cy + minSide * 0.015;
  const filterH = minSide * 0.032;
  const filterTop = filterY - filterH * 0.5;
  const filterBot = filterY + filterH * 0.5;

  // 4. Clean Flanking Purity Ripple Arcs (Strictly along left/right curved flanks ONLY — NEVER crosses top collar or bottom valve!)
  if (rippleStrength > 0.01) {
    for (let r = 0; r < 2; r++) {
      const rNorm = (cycleNorm * 3 + r * 0.5) % 1;
      const expand = minSide * (0.016 + 0.026 * rNorm);
      const rAlpha = Math.sin(Math.PI * rNorm) * rippleStrength * 0.62;

      if (rAlpha > 0.02) {
        for (let side = -1; side <= 1; side += 2) {
          const sxTop = dropX + side * (bellyHalfW * 0.66 + expand * 0.72);
          const syTop = dropTop + dropH * 0.30;
          const sxMid = dropX + side * (bellyHalfW + expand);
          const syMid = bellyY;
          const sxBot = dropX + side * (bellyHalfW * 0.64 + expand * 0.72);
          const syBot = dropBot - dropH * 0.08;

          ctx.beginPath();
          ctx.moveTo(sxTop, syTop);
          ctx.bezierCurveTo(
            dropX + side * (bellyHalfW * 0.96 + expand),
            syMid - dropH * 0.14,
            sxMid,
            syMid - dropH * 0.05,
            sxMid,
            syMid
          );
          ctx.bezierCurveTo(
            sxMid,
            syMid + dropH * 0.08,
            dropX + side * (bellyHalfW * 0.90 + expand * 0.88),
            syBot - dropH * 0.03,
            sxBot,
            syBot
          );
          ctx.lineCap = "round";
          ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
          ctx.strokeStyle = "rgba(0, 229, 255, " + rAlpha.toFixed(3) + ")";
          ctx.stroke();
        }
      }
    }
  }

  // 5. Left Volumetric Precision Scale Gauge (Clearance >= 0.055 * minSide from vessel left wall)
  const scaleX = cx - minSide * 0.275;
  const scaleTop = filterBot + minSide * 0.022;
  const scaleBot = dropBot - minSide * 0.040;
  const scaleSpan = scaleBot - scaleTop;

  ctx.beginPath();
  ctx.moveTo(scaleX, scaleTop);
  ctx.lineTo(scaleX, scaleBot);
  ctx.lineCap = "round";
  ctx.lineWidth = Math.max(2, minSide * 0.004);
  ctx.strokeStyle = "#1E3A6E";
  ctx.stroke();

  const tickCount = 7;
  for (let i = 0; i < tickCount; i++) {
    const ty = scaleTop + (scaleSpan * i) / (tickCount - 1);
    const isMajor = i % 2 === 0;
    const tickLen = minSide * (isMajor ? 0.016 : 0.009);
    ctx.beginPath();
    ctx.moveTo(scaleX, ty);
    ctx.lineTo(scaleX + tickLen, ty);
    ctx.lineCap = "round";
    ctx.lineWidth = Math.max(1.5, minSide * 0.0028);
    ctx.strokeStyle = isMajor ? "#7CE8FF" : "#3B66A3";
    ctx.stroke();
  }

  const ptrY = scaleBot - scaleSpan * lowerLevel;
  const ptrW = minSide * 0.020;
  const ptrH = minSide * 0.010;
  roundedRectPath(scaleX - ptrW - minSide * 0.008, ptrY - ptrH * 0.5, ptrW, ptrH, ptrH * 0.5);
  ctx.fillStyle = "#00E5FF";
  ctx.fill();

  // 6. Overhead Intake Pipe
  const pipeBendR = minSide * 0.045;
  const pipeStartX = dropX - minSide * 0.135;
  const pipeTopY = dropTop - minSide * 0.088;
  const pipeStrokeW = minSide * 0.028;

  ctx.beginPath();
  ctx.moveTo(pipeStartX, pipeTopY);
  ctx.lineTo(dropX - pipeBendR, pipeTopY);
  ctx.quadraticCurveTo(dropX, pipeTopY, dropX, pipeTopY + pipeBendR);
  ctx.lineTo(dropX, dropTop + minSide * 0.008);
  ctx.lineCap = "round";
  ctx.lineWidth = pipeStrokeW;
  ctx.strokeStyle = "#334E7D";
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(pipeStartX, pipeTopY);
  ctx.lineTo(dropX - pipeBendR, pipeTopY);
  ctx.quadraticCurveTo(dropX, pipeTopY, dropX, pipeTopY + pipeBendR);
  ctx.lineTo(dropX, dropTop + minSide * 0.006);
  ctx.lineCap = "round";
  ctx.lineWidth = pipeStrokeW * 0.42;
  ctx.strokeStyle = pourRate > 0.02 ? "#FB7185" : "#1B2E52";
  ctx.stroke();

  // 7. Bottom Precision Outlet Valve & Clean Exit Droplets (Scene 2 reset)
  const valveW = minSide * 0.068;
  const valveH = minSide * 0.030;
  const valveY = dropBot - minSide * 0.003;

  const dropGate = smoothRange(valveOpen, 0.18, 0.45);
  if (dropGate > 0.01) {
    // Clean descending purified droplets exiting smoothly from bottom nozzle
    for (let k = 0; k < 2; k++) {
      const kProg = (cycleNorm * 6 + k * 0.5) % 1;
      const kAlpha = Math.sin(Math.PI * kProg) * dropGate * 0.92;
      if (kAlpha > 0.04) {
        const ky = valveY + valveH + minSide * (0.008 + 0.042 * kProg);
        const kr = minSide * 0.0062;
        ctx.beginPath();
        ctx.moveTo(dropX, ky - kr * 1.4);
        ctx.quadraticCurveTo(dropX + kr, ky + kr * 0.1, dropX, ky + kr);
        ctx.quadraticCurveTo(dropX - kr, ky + kr * 0.1, dropX, ky - kr * 1.4);
        ctx.closePath();
        ctx.fillStyle = "rgba(0, 229, 255, " + kAlpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  roundedRectPath(dropX - valveW * 0.5, valveY, valveW, valveH, minSide * 0.010);
  ctx.fillStyle = "#1E3A6E";
  ctx.fill();
  ctx.lineWidth = minSide * 0.005;
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  ctx.save();
  ctx.translate(dropX, valveY + valveH * 0.5);
  ctx.rotate(valveOpen * Math.PI * 0.5);
  roundedRectPath(-minSide * 0.012, -minSide * 0.0035, minSide * 0.024, minSide * 0.007, minSide * 0.0035);
  ctx.fillStyle = valveOpen > 0.1 ? "#00E5FF" : "#94A3B8";
  ctx.fill();
  ctx.restore();

  // 8. Main Glass Teardrop Vessel Interior (Strictly Clipped)
  const wallInset = minSide * 0.014;
  traceTeardropPath(
    dropX,
    dropTop + wallInset * 0.6,
    dropBot - wallInset,
    neckHalfW - wallInset * 0.7,
    bellyHalfW - wallInset,
    bellyY
  );
  ctx.fillStyle = "#071530";
  ctx.fill();

  ctx.save();
  traceTeardropPath(
    dropX,
    dropTop + wallInset * 0.6,
    dropBot - wallInset,
    neckHalfW - wallInset * 0.7,
    bellyHalfW - wallInset,
    bellyY
  );
  ctx.clip();

  // Subtle flat-vector right interior shadow crescent
  ctx.fillStyle = "#051026";
  ctx.fillRect(dropX + bellyHalfW * 0.35, dropTop, bellyHalfW, dropH);

  // --- UPPER CHAMBER ---
  const upperChamberTop = dropTop + minSide * 0.025;
  const upperChamberBot = filterTop;
  const upperChamberH = upperChamberBot - upperChamberTop;
  const upperSurfaceY = upperChamberBot - upperChamberH * upperLevel;
  const upperWaveAmp = minSide * 0.006 * (0.35 + 0.65 * pourRate + 0.25 * filterFlow) * clamp01(upperLevel * 8);

  // Pouring Stream entering upper chamber (descends cleanly to upperSurfaceY without crossing filterTop)
  if (pourRate > 0.015 && pourReach > 0.01) {
    const streamW = minSide * 0.015 * pourRate;
    const streamTopY = dropTop + wallInset * 0.5;
    const targetBotY = Math.min(upperChamberBot, upperSurfaceY + minSide * 0.008);
    const streamBotY = lerp(streamTopY, targetBotY, pourReach);
    const stepsStream = 18;

    if (streamBotY > streamTopY + minSide * 0.005) {
      ctx.beginPath();
      for (let s = 0; s <= stepsStream; s++) {
        const u = s / stepsStream;
        const sy = lerp(streamTopY, streamBotY, u);
        const sway = Math.sin(u * Math.PI * 2 - wavePhase1 * 1.5) * minSide * 0.0032 * u;
        const half = streamW * (0.55 - 0.14 * u);
        if (s === 0) ctx.moveTo(dropX + sway - half, sy);
        else ctx.lineTo(dropX + sway - half, sy);
      }
      for (let s = stepsStream; s >= 0; s--) {
        const u = s / stepsStream;
        const sy = lerp(streamTopY, streamBotY, u);
        const sway = Math.sin(u * Math.PI * 2 - wavePhase1 * 1.5) * minSide * 0.0032 * u;
        const half = streamW * (0.55 - 0.14 * u);
        ctx.lineTo(dropX + sway + half, sy);
      }
      ctx.closePath();
      ctx.fillStyle = "#FB7185";
      ctx.fill();
    }
  }

  // Upper Impure Pool (Visible cleanly only when upperLevel > 0.008)
  const wSteps = 36;
  if (upperLevel > 0.008) {
    ctx.beginPath();
    ctx.moveTo(dropX - bellyHalfW, upperChamberBot);
    for (let s = 0; s <= wSteps; s++) {
      const u = s / wSteps;
      const wx = dropX - bellyHalfW + u * bellyHalfW * 2;
      const wy = Math.min(upperChamberBot, upperSurfaceY + Math.sin(u * Math.PI * 2.4 + wavePhase1) * upperWaveAmp);
      ctx.lineTo(wx, wy);
    }
    ctx.lineTo(dropX + bellyHalfW, upperChamberBot);
    ctx.closePath();

    const upGrad = ctx.createLinearGradient(dropX, upperSurfaceY - upperWaveAmp, dropX, upperChamberBot);
    upGrad.addColorStop(0, "#FB7185");
    upGrad.addColorStop(1, "#BE123C");
    ctx.fillStyle = upGrad;
    ctx.fill();

    // Crisp meniscus
    ctx.beginPath();
    for (let s = 0; s <= wSteps; s++) {
      const u = s / wSteps;
      const wx = dropX - bellyHalfW + u * bellyHalfW * 2;
      const wy = Math.min(upperChamberBot, upperSurfaceY + Math.sin(u * Math.PI * 2.4 + wavePhase1) * upperWaveAmp);
      if (s === 0) ctx.moveTo(wx, wy);
      else ctx.lineTo(wx, wy);
    }
    ctx.lineWidth = Math.max(1.2, minSide * 0.0024);
    ctx.strokeStyle = "#FECDD3";
    ctx.stroke();

    // Suspended pollutant specs strictly inside upper pool
    const impTop = upperSurfaceY + minSide * 0.014;
    const impBot = upperChamberBot - minSide * 0.012;
    if (impBot > impTop + minSide * 0.012) {
      const specs = [
        { xOff: -0.055, phase: 0.1, r: 0.0042 },
        { xOff: -0.022, phase: 0.45, r: 0.0034 },
        { xOff: 0.018, phase: 0.72, r: 0.0044 },
        { xOff: 0.052, phase: 0.28, r: 0.0036 },
      ];
      for (let i = 0; i < specs.length; i++) {
        const sp = specs[i];
        const pLoop = (cycleNorm * 3 + sp.phase) % 1;
        const sy = lerp(impTop, impBot, pLoop);
        const sx = dropX + sp.xOff * minSide + Math.sin(pLoop * Math.PI * 2) * minSide * 0.006;
        const sAlpha = Math.sin(Math.PI * pLoop) * (0.45 + 0.45 * clamp01(upperLevel));
        if (sAlpha > 0.04) {
          ctx.beginPath();
          ctx.arc(sx, sy, minSide * sp.r, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(255, 228, 230, " + sAlpha.toFixed(3) + ")";
          ctx.fill();
        }
      }
    }
  }

  // --- LOWER CHAMBER ---
  const lowerChamberTop = filterBot;
  const lowerChamberBot = dropBot - wallInset;
  const lowerChamberH = lowerChamberBot - lowerChamberTop;
  const lowerSurfaceY = lowerChamberBot - lowerChamberH * lowerLevel;
  const lowerWaveAmp = minSide * 0.0075 * (0.55 + 0.45 * Math.sin(cycleNorm * Math.PI * 2 * 3));

  // Falling Purified Droplets aligned directly beneath pores #2, #3, #4 (-0.0425, 0, +0.0425)
  const dropGap = lowerSurfaceY - filterBot;
  if (filterFlow > 0.06 && dropGap > minSide * 0.026) {
    const dripLanes = [-0.0425, 0.0, 0.0425];
    for (let d = 0; d < dripLanes.length; d++) {
      const dProg = (cycleNorm * 7 + d * 0.333) % 1;
      const accelY = dProg * dProg;
      const dy = lerp(filterBot + minSide * 0.008, lowerSurfaceY - minSide * 0.006, accelY);
      const dx = dropX + dripLanes[d] * minSide;
      const dr = minSide * 0.0068 * filterFlow;
      const dAlpha = filterFlow * Math.sin(Math.PI * clamp01(dProg * 0.9 + 0.05));

      if (dy < lowerSurfaceY - dr && dAlpha > 0.05) {
        ctx.beginPath();
        ctx.moveTo(dx, dy - dr * 1.45);
        ctx.quadraticCurveTo(dx + dr, dy + dr * 0.1, dx, dy + dr);
        ctx.quadraticCurveTo(dx - dr, dy + dr * 0.1, dx, dy - dr * 1.45);
        ctx.closePath();
        ctx.fillStyle = "rgba(124, 232, 255, " + dAlpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // Lower Purified Back Wave
  ctx.beginPath();
  ctx.moveTo(dropX - bellyHalfW, lowerChamberBot);
  for (let s = 0; s <= wSteps; s++) {
    const u = s / wSteps;
    const wx = dropX - bellyHalfW + u * bellyHalfW * 2;
    const wy =
      lowerSurfaceY -
      minSide * 0.0035 +
      Math.sin(u * Math.PI * 2.2 - wavePhase1 + 1.0) * lowerWaveAmp * 0.8;
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(dropX + bellyHalfW, lowerChamberBot);
  ctx.closePath();
  ctx.fillStyle = "#0284C7";
  ctx.fill();

  // Lower Purified Front Wave
  ctx.beginPath();
  ctx.moveTo(dropX - bellyHalfW, lowerChamberBot);
  for (let s = 0; s <= wSteps; s++) {
    const u = s / wSteps;
    const wx = dropX - bellyHalfW + u * bellyHalfW * 2;
    const wy =
      lowerSurfaceY +
      Math.sin(u * Math.PI * 2.0 + wavePhase1) * lowerWaveAmp +
      Math.cos(u * Math.PI * 3.2 - wavePhase2) * (lowerWaveAmp * 0.22);
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(dropX + bellyHalfW, lowerChamberBot);
  ctx.closePath();

  const lowGrad = ctx.createLinearGradient(dropX, lowerSurfaceY - lowerWaveAmp, dropX, lowerChamberBot);
  lowGrad.addColorStop(0, "#00E5FF");
  lowGrad.addColorStop(0.45, "#0EA5E9");
  lowGrad.addColorStop(1, "#1D4ED8");
  ctx.fillStyle = lowGrad;
  ctx.fill();

  // Crisp cyan meniscus highlight
  ctx.beginPath();
  for (let s = 0; s <= wSteps; s++) {
    const u = s / wSteps;
    const wx = dropX - bellyHalfW + u * bellyHalfW * 2;
    const wy =
      lowerSurfaceY +
      Math.sin(u * Math.PI * 2.0 + wavePhase1) * lowerWaveAmp +
      Math.cos(u * Math.PI * 3.2 - wavePhase2) * (lowerWaveAmp * 0.22);
    if (s === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.lineWidth = Math.max(1.5, minSide * 0.0028);
  ctx.strokeStyle = "#BAE6FD";
  ctx.stroke();

  // Pure Aeration Bubbles Inside Lower Pool
  const pureBubbles = [
    { xOff: -0.072, speed: 3, phase: 0.12, r: 0.0046 },
    { xOff: -0.025, speed: 4, phase: 0.58, r: 0.0036 },
    { xOff: 0.032, speed: 3, phase: 0.32, r: 0.0048 },
    { xOff: 0.074, speed: 4, phase: 0.80, r: 0.0034 },
  ];
  const pBubBot = lowerChamberBot - minSide * 0.020;
  const pBubTop = lowerSurfaceY + minSide * 0.016;
  if (pBubBot > pBubTop + minSide * 0.018) {
    for (let i = 0; i < pureBubbles.length; i++) {
      const b = pureBubbles[i];
      const prog = (cycleNorm * b.speed + b.phase) % 1;
      const by = lerp(pBubBot, pBubTop, prog);
      const bx = dropX + b.xOff * minSide + Math.sin(prog * Math.PI * 2) * minSide * 0.004;
      const bAlpha = Math.sin(Math.PI * prog) * 0.72;
      if (bAlpha > 0.04) {
        ctx.beginPath();
        ctx.arc(bx, by, minSide * b.r, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(224, 247, 250, " + bAlpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // --- CENTRAL MULTI-LAYER CARBON FILTRATION MEMBRANE ---
  ctx.fillStyle = "#1E293B";
  ctx.fillRect(dropX - bellyHalfW, filterTop, bellyHalfW * 2, filterH);

  ctx.fillStyle = "#64748B";
  ctx.fillRect(dropX - bellyHalfW, filterTop, bellyHalfW * 2, minSide * 0.004);
  ctx.fillRect(dropX - bellyHalfW, filterBot - minSide * 0.004, bellyHalfW * 2, minSide * 0.004);

  const poreCount = 5;
  const poreSpan = minSide * 0.17;
  const poreW = minSide * 0.016;
  const poreH = filterH - minSide * 0.014;
  for (let p = 0; p < poreCount; p++) {
    const px = dropX - poreSpan * 0.5 + (poreSpan * p) / (poreCount - 1) - poreW * 0.5;
    const py = filterY - poreH * 0.5;
    roundedRectPath(px, py, poreW, poreH, poreW * 0.45);
    ctx.fillStyle = "#0F172A";
    ctx.fill();

    if (filterFlow > 0.02) {
      const pulse = 0.5 + 0.5 * Math.sin(cycleNorm * Math.PI * 2 * 5 - p * 0.8);
      const fillH = poreH * clamp01(filterFlow * (0.5 + 0.5 * pulse));
      roundedRectPath(px + minSide * 0.002, py + minSide * 0.002, poreW - minSide * 0.004, fillH - minSide * 0.002, poreW * 0.35);
      ctx.fillStyle = "#00E5FF";
      ctx.fill();
    }
  }

  // Crisp curved glass specular arc on left interior curve
  ctx.beginPath();
  ctx.moveTo(dropX - neckHalfW * 0.65, dropTop + minSide * 0.045);
  ctx.bezierCurveTo(
    dropX - bellyHalfW * 0.72,
    bellyY - dropH * 0.16,
    dropX - bellyHalfW * 0.84,
    bellyY + dropH * 0.05,
    dropX - bellyHalfW * 0.58,
    dropBot - minSide * 0.045
  );
  ctx.lineCap = "round";
  ctx.lineWidth = minSide * 0.0065;
  ctx.strokeStyle = "rgba(234, 248, 255, 0.22)";
  ctx.stroke();

  ctx.restore();

  // Crisp Outer Glass Teardrop Rim
  traceTeardropPath(dropX, dropTop, dropBot, neckHalfW, bellyHalfW, bellyY);
  ctx.lineWidth = minSide * 0.0075;
  ctx.strokeStyle = "#D8F3FF";
  ctx.stroke();

  // Sleek Top Laboratory Collar Ring seated cleanly over top neck port
  const collarW = neckHalfW * 2.55;
  const collarH = minSide * 0.022;
  roundedRectPath(dropX - collarW * 0.5, dropTop - collarH * 0.45, collarW, collarH, collarH * 0.45);
  ctx.fillStyle = "#1E3A6E";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0045;
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  // 9. Right Reactive Purity Gauge Badge (Clearance >= 0.064 * minSide from droplet right wall)
  const badgeX = cx + minSide * 0.262;
  const badgeY = cy - minSide * 0.025;
  const badgeR = minSide * 0.065;

  const badgeColor = lerpColor([251, 113, 133], [0, 229, 255], purityScore);

  ctx.beginPath();
  ctx.arc(badgeX, badgeY, badgeR, 0, Math.PI * 2);
  ctx.fillStyle = "#0B1F47";
  ctx.fill();

  ctx.beginPath();
  ctx.arc(badgeX, badgeY, badgeR - minSide * 0.0075, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.008;
  ctx.strokeStyle = "#172E5C";
  ctx.stroke();

  const arcSweep = Math.PI * 2 * (0.20 + 0.80 * purityScore);
  ctx.beginPath();
  ctx.arc(badgeX, badgeY, badgeR - minSide * 0.0075, -Math.PI * 0.5, -Math.PI * 0.5 + arcSweep);
  ctx.lineCap = "round";
  ctx.lineWidth = minSide * 0.008;
  ctx.strokeStyle = badgeColor;
  ctx.stroke();

  const iconOpacityWave = 1 - smoothRange(checkTrim, 0.0, 0.32);
  if (iconOpacityWave > 0.01) {
    ctx.beginPath();
    const wSpan = badgeR * 0.48;
    const wStepsIcon = 16;
    for (let s = 0; s <= wStepsIcon; s++) {
      const u = s / wStepsIcon;
      const ix = badgeX - wSpan + u * wSpan * 2;
      const iy = badgeY + Math.sin(u * Math.PI * 2 + wavePhase1) * minSide * 0.0065 * (1 - purityScore * 0.45);
      if (s === 0) ctx.moveTo(ix, iy);
      else ctx.lineTo(ix, iy);
    }
    ctx.lineCap = "round";
    ctx.lineWidth = minSide * 0.0062;
    ctx.strokeStyle = badgeColor;
    ctx.globalAlpha = iconOpacityWave;
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  const checkDraw = smoothRange(checkTrim, 0.34, 1.0);
  if (checkDraw > 0.01) {
    const p0x = badgeX - badgeR * 0.34;
    const p0y = badgeY + badgeR * 0.03;
    const p1x = badgeX - badgeR * 0.06;
    const p1y = badgeY + badgeR * 0.28;
    const p2x = badgeX + badgeR * 0.38;
    const p2y = badgeY - badgeR * 0.24;

    const seg1 = clamp01(checkDraw / 0.42);
    const seg2 = clamp01((checkDraw - 0.42) / 0.58);

    ctx.beginPath();
    ctx.moveTo(p0x, p0y);
    ctx.lineTo(lerp(p0x, p1x, seg1), lerp(p0y, p1y, seg1));
    if (seg2 > 0) {
      ctx.lineTo(lerp(p1x, p2x, seg2), lerp(p1y, p2y, seg2));
    }
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.lineWidth = minSide * 0.0078;
    ctx.strokeStyle = "#34D399";
    ctx.stroke();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawLeaf(x, y, angle, length, widthFactor, openAmt, colorLeft, colorRight, borderColor, borderW) {
    if (openAmt <= 0.005 || length <= 0.5) return;
    const len = length * openAmt;
    const halfW = len * widthFactor;

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    // Outer separator stroke for crisp contrast against liquid behind
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(len * 0.28, -halfW, len * 0.76, -halfW * 0.72, len, 0);
    ctx.bezierCurveTo(len * 0.76, halfW * 0.72, len * 0.28, halfW, 0, 0);
    ctx.closePath();
    ctx.lineJoin = "round";
    ctx.lineWidth = borderW;
    ctx.strokeStyle = borderColor;
    ctx.stroke();

    // Upper/left flat vector shade
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(len * 0.28, -halfW, len * 0.76, -halfW * 0.72, len, 0);
    ctx.lineTo(0, 0);
    ctx.closePath();
    ctx.fillStyle = colorLeft;
    ctx.fill();

    // Lower/right flat vector shade
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(len, 0);
    ctx.bezierCurveTo(len * 0.76, halfW * 0.72, len * 0.28, halfW, 0, 0);
    ctx.closePath();
    ctx.fillStyle = colorRight;
    ctx.fill();

    // Crisp central leaf vein
    ctx.beginPath();
    ctx.moveTo(len * 0.14, 0);
    ctx.lineTo(len * 0.78, 0);
    ctx.lineCap = "round";
    ctx.lineWidth = Math.max(1, minSide * 0.0024);
    ctx.strokeStyle = "#ECFDF5";
    ctx.stroke();

    ctx.restore();
  }

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#041418");
  bgGrad.addColorStop(0.52, "#071F24");
  bgGrad.addColorStop(1, "#0B2D33");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let wingDeploy = 0;
  let wingBreath = 0;
  let photonAlpha = 0;
  let chargeLevel = 0.24;
  let stemGrow = 0.24;
  let lowerLeavesOpen = 0.20;
  let upperLeavesOpen = 0;
  let crownLeafOpen = 0;
  let exportFlow = 0;

  if (currentScene === 0) {
    wingDeploy = smoothRange(sceneProgress, 0.06, 0.65);
    photonAlpha = smoothRange(sceneProgress, 0.42, 0.90);
    chargeLevel = 0.24 + 0.38 * easeInOutSine(sceneProgress);
    stemGrow = 0.24 + 0.44 * easeInOutSine(sceneProgress);
    lowerLeavesOpen = 0.20 + 0.55 * smoothRange(sceneProgress, 0.14, 0.96);
    upperLeavesOpen = 0;
    crownLeafOpen = 0;
    exportFlow = 0;
  } else if (currentScene === 1) {
    wingDeploy = 1;
    wingBreath = Math.sin(Math.PI * sceneProgress) * 0.032;
    photonAlpha = 1 - 0.72 * smoothRange(sceneProgress, 0.70, 1.0);
    chargeLevel = 0.62 + 0.26 * smoothRange(sceneProgress, 0.0, 0.74);
    stemGrow = 0.68 + 0.32 * smoothRange(sceneProgress, 0.0, 0.62);
    lowerLeavesOpen = 0.75 + 0.25 * smoothRange(sceneProgress, 0.0, 0.45);
    upperLeavesOpen = smoothRange(sceneProgress, 0.18, 0.78);
    crownLeafOpen = smoothRange(sceneProgress, 0.46, 0.92);
    exportFlow = smoothRange(sceneProgress, 0.68, 1.0);
  } else {
    wingDeploy = 1 - smoothRange(sceneProgress, 0.28, 0.92);
    photonAlpha = 0.28 * (1 - smoothRange(sceneProgress, 0.0, 0.30));
    chargeLevel = 0.88 - 0.64 * smoothRange(sceneProgress, 0.14, 0.95);
    stemGrow = 1.0 - 0.76 * smoothRange(sceneProgress, 0.16, 0.95);
    lowerLeavesOpen = 1.0 - 0.80 * smoothRange(sceneProgress, 0.20, 0.92);
    upperLeavesOpen = 1.0 - smoothRange(sceneProgress, 0.12, 0.76);
    crownLeafOpen = 1.0 - smoothRange(sceneProgress, 0.05, 0.60);
    exportFlow = 1 - smoothRange(sceneProgress, 0.62, 1.0);
  }

  // Exact integer harmonics across 20s for seamless looping
  const wavePhase1 = cycleNorm * Math.PI * 2 * 6;
  const wavePhase2 = cycleNorm * Math.PI * 2 * 9;
  const leafSway = Math.sin(cycleNorm * Math.PI * 2 * 3) * 0.042;

  // 3. Layout Coordinates (Strictly proportional to minSide, balanced spacing)
  const cx = width * 0.5;
  const batCy = height * 0.57;
  const batW = minSide * 0.28;
  const batH = minSide * 0.44;
  const batR = minSide * 0.042;
  const batLeft = cx - batW * 0.5;
  const batRight = cx + batW * 0.5;
  const batTop = batCy - batH * 0.5;
  const batBot = batCy + batH * 0.5;

  const termW = batW * 0.40;
  const termH = minSide * 0.026;
  const termTop = batTop - termH;

  const mastH = minSide * 0.044;
  const hubY = termTop - mastH;

  // 4. Lateral Segmented Charge Telemetry Arcs (Clearance > 0.06 * minSide from battery & solar wings)
  const arcRadius = minSide * 0.242;
  const arcStrokeW = minSide * 0.012;
  const segCount = 5;
  const segSpan = 0.195;
  const segGap = 0.042;
  const totalHalfSpan = segCount * segSpan + (segCount - 1) * segGap;

  for (let side = -1; side <= 1; side += 2) {
    const baseAngle = side === 1 ? 0 : Math.PI;
    const startBase = baseAngle - totalHalfSpan * 0.5;

    for (let i = 0; i < segCount; i++) {
      const idx = side === 1 ? segCount - 1 - i : i;
      const a0 = startBase + idx * (segSpan + segGap);
      const a1 = a0 + segSpan;

      const segThreshold = i / segCount;
      const segFill = clamp01((chargeLevel - segThreshold) * segCount);

      ctx.beginPath();
      ctx.arc(cx, batCy, arcRadius, a0, a1);
      ctx.lineCap = "round";
      ctx.lineWidth = arcStrokeW;
      ctx.strokeStyle = "#0D373E";
      ctx.stroke();

      if (segFill > 0.01) {
        const activeStart = side === 1 ? a1 - segSpan * segFill : a0;
        const activeEnd = side === 1 ? a1 : a0 + segSpan * segFill;
        ctx.beginPath();
        ctx.arc(cx, batCy, arcRadius, activeStart, activeEnd);
        ctx.lineCap = "round";
        ctx.lineWidth = arcStrokeW;
        ctx.strokeStyle = i >= 3 ? "#84F542" : "#10D98B";
        ctx.stroke();
      }
    }

    // Crisp outer export pulse dashes gliding along dedicated outer curved rail (Scene 1 tail -> Scene 2)
    if (exportFlow > 0.01) {
      const outerR = minSide * 0.278;
      const railSpan = totalHalfSpan * 0.88;
      const railStart = baseAngle - railSpan * 0.5;
      const railEnd = baseAngle + railSpan * 0.5;

      // Subtle guide rail
      ctx.beginPath();
      ctx.arc(cx, batCy, outerR, railStart, railEnd);
      ctx.lineCap = "round";
      ctx.lineWidth = Math.max(1.5, minSide * 0.003);
      ctx.strokeStyle = "rgba(16, 217, 139, " + (exportFlow * 0.22).toFixed(3) + ")";
      ctx.stroke();

      const dashCount = 3;
      const dashArc = 0.085;
      for (let p = 0; p < dashCount; p++) {
        const flowNorm = (cycleNorm * 4 + p / dashCount) % 1;
        const alpha = Math.sin(Math.PI * flowNorm) * exportFlow;
        if (alpha > 0.02) {
          const centerOffset = (0.5 - flowNorm) * (railSpan - dashArc);
          const midAng = baseAngle + (side === 1 ? centerOffset : -centerOffset);
          ctx.beginPath();
          ctx.arc(cx, batCy, outerR, midAng - dashArc * 0.5, midAng + dashArc * 0.5);
          ctx.lineCap = "round";
          ctx.lineWidth = minSide * 0.0065;
          ctx.strokeStyle = "rgba(132, 245, 66, " + (alpha * 0.92).toFixed(3) + ")";
          ctx.stroke();
        }
      }
    }
  }

  // 5. Top Solar Mast, Collector Hub & Folding Solar Wings
  const mastW = minSide * 0.014;
  ctx.fillStyle = "#1E4E55";
  ctx.fillRect(cx - mastW * 0.5, hubY, mastW, mastH + minSide * 0.004);

  if (photonAlpha > 0.01 || chargeLevel > 0.3) {
    const coreAlpha = Math.max(photonAlpha * 0.9, 0.25);
    ctx.fillStyle = "rgba(255, 184, 48, " + coreAlpha.toFixed(3) + ")";
    ctx.fillRect(cx - mastW * 0.18, hubY + minSide * 0.006, mastW * 0.36, mastH - minSide * 0.006);
  }

  const wingPivotOffset = minSide * 0.032;
  const wingLen = minSide * 0.130;
  const wingThick = minSide * 0.036;
  const wingR = minSide * 0.009;

  for (let side = -1; side <= 1; side += 2) {
    const pivotX = cx + side * wingPivotOffset;
    const pivotY = hubY;
    const stowedAngle = side === 1 ? -Math.PI * 0.472 : -Math.PI * 0.528;
    const openAngle = side === 1 ? -Math.PI * 0.078 - wingBreath : -Math.PI * 0.922 + wingBreath;
    const angle = stowedAngle + (openAngle - stowedAngle) * wingDeploy;

    ctx.save();
    ctx.translate(pivotX, pivotY);
    ctx.rotate(angle);

    ctx.fillStyle = "#34D399";
    ctx.fillRect(-minSide * 0.004, -minSide * 0.007, minSide * 0.014, minSide * 0.014);

    const panelStart = minSide * 0.006;
    const panelW = wingLen - panelStart;
    const panelY = -wingThick * 0.5;

    roundedRectPath(panelStart, panelY, panelW, wingThick, wingR);
    ctx.fillStyle = "#12344D";
    ctx.fill();
    ctx.lineWidth = minSide * 0.0045;
    ctx.strokeStyle = "#A7F3D0";
    ctx.stroke();

    ctx.save();
    roundedRectPath(panelStart + minSide * 0.004, panelY + minSide * 0.004, panelW - minSide * 0.008, wingThick - minSide * 0.008, wingR * 0.7);
    ctx.clip();

    const cellLit = photonAlpha * 0.34;
    const cellGrad = ctx.createLinearGradient(panelStart, panelY, panelStart + panelW, panelY + wingThick);
    cellGrad.addColorStop(0, "#1E4B6E");
    cellGrad.addColorStop(1, "#0E293D");
    ctx.fillStyle = cellGrad;
    ctx.fillRect(panelStart, panelY, panelW, wingThick);

    if (cellLit > 0.01) {
      ctx.fillStyle = "rgba(255, 184, 48, " + cellLit.toFixed(3) + ")";
      ctx.fillRect(panelStart, panelY, panelW, wingThick * 0.44);
    }

    ctx.strokeStyle = "#38BDF8";
    ctx.lineWidth = Math.max(1, minSide * 0.0022);
    ctx.beginPath();
    ctx.moveTo(panelStart, 0);
    ctx.lineTo(panelStart + panelW, 0);
    for (let c = 1; c <= 3; c++) {
      const gx = panelStart + (panelW * c) / 4;
      ctx.moveTo(gx, panelY);
      ctx.lineTo(gx, panelY + wingThick);
    }
    ctx.stroke();
    ctx.restore();

    ctx.restore();
  }

  // Central Solar Hub Joint
  ctx.beginPath();
  ctx.arc(cx, hubY, minSide * 0.020, 0, Math.PI * 2);
  ctx.fillStyle = "#0C2D33";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0045;
  ctx.strokeStyle = "#A7F3D0";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, hubY, minSide * 0.0085, 0, Math.PI * 2);
  ctx.fillStyle = photonAlpha > 0.15 ? "#FFB830" : "#34D399";
  ctx.fill();

  // 6. Symmetrical Solar Photon Capsules Above Open Wings (Zero asymmetry, zero collision with wings)
  if (photonAlpha > 0.01 && wingDeploy > 0.5) {
    const rayVisibility = photonAlpha * smoothRange(wingDeploy, 0.5, 1.0);
    const photonPairs = [
      { offset: 0.068, phase: 0.0 },
      { offset: 0.122, phase: 0.5 },
    ];
    const startSkyY = hubY - minSide * 0.158;
    const endSkyY = hubY - minSide * 0.060;

    for (let i = 0; i < photonPairs.length; i++) {
      const pair = photonPairs[i];
      const pNorm = (cycleNorm * 5 + pair.phase) % 1;
      const fade = Math.sin(Math.PI * pNorm) * rayVisibility;
      if (fade > 0.02) {
        const ry = startSkyY + (endSkyY - startSkyY) * pNorm;
        const rLen = minSide * 0.026;
        for (let side = -1; side <= 1; side += 2) {
          const rx = cx + side * pair.offset * minSide;
          ctx.beginPath();
          ctx.moveTo(rx, ry);
          ctx.lineTo(rx, ry + rLen);
          ctx.lineCap = "round";
          ctx.lineWidth = minSide * 0.006;
          ctx.strokeStyle = "rgba(255, 184, 48, " + fade.toFixed(3) + ")";
          ctx.stroke();

          ctx.beginPath();
          ctx.arc(rx, ry + rLen, minSide * 0.0046, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(253, 230, 138, " + fade.toFixed(3) + ")";
          ctx.fill();
        }
      }
    }
  }

  // 7. Battery Terminal Cap
  const termR = minSide * 0.012;
  ctx.beginPath();
  ctx.moveTo(cx - termW * 0.5, batTop);
  ctx.lineTo(cx - termW * 0.5, termTop + termR);
  ctx.quadraticCurveTo(cx - termW * 0.5, termTop, cx - termW * 0.5 + termR, termTop);
  ctx.lineTo(cx + termW * 0.5 - termR, termTop);
  ctx.quadraticCurveTo(cx + termW * 0.5, termTop, cx + termW * 0.5, termTop + termR);
  ctx.lineTo(cx + termW * 0.5, batTop);
  ctx.closePath();
  ctx.fillStyle = "#104942";
  ctx.fill();
  ctx.lineWidth = minSide * 0.006;
  ctx.strokeStyle = "#D8FFF0";
  ctx.stroke();

  // 8. Main Battery Shell & Interior Clipped Scene
  const pad = minSide * 0.018;
  const inLeft = batLeft + pad;
  const inRight = batRight - pad;
  const inTop = batTop + pad;
  const inBot = batBot - pad;
  const inW = inRight - inLeft;
  const inH = inBot - inTop;
  const inR = batR - pad * 0.72;

  roundedRectPath(batLeft, batTop, batW, batH, batR);
  ctx.fillStyle = "#082227";
  ctx.fill();

  ctx.save();
  roundedRectPath(inLeft, inTop, inW, inH, inR);
  ctx.clip();

  ctx.fillStyle = "#05171B";
  ctx.fillRect(inLeft, inTop, inW, inH);
  ctx.fillStyle = "#041216";
  ctx.fillRect(inLeft + inW * 0.68, inTop, inW * 0.32, inH);

  // Liquid Wave Calculation
  const surfaceY = inBot - inH * chargeLevel;
  const waveAmp = minSide * 0.0085 * (0.65 + 0.35 * Math.sin(cycleNorm * Math.PI * 2 * 3));

  // Back Liquid Wave Layer
  ctx.beginPath();
  ctx.moveTo(inLeft, inBot);
  const steps = 40;
  for (let s = 0; s <= steps; s++) {
    const u = s / steps;
    const wx = inLeft + u * inW;
    const wy =
      surfaceY -
      minSide * 0.004 +
      Math.sin(u * Math.PI * 2.2 - wavePhase1 + 1.1) * waveAmp * 0.85;
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(inRight, inBot);
  ctx.closePath();
  ctx.fillStyle = "#059669";
  ctx.fill();

  // Front Liquid Wave Layer
  ctx.beginPath();
  ctx.moveTo(inLeft, inBot);
  for (let s = 0; s <= steps; s++) {
    const u = s / steps;
    const wx = inLeft + u * inW;
    const wy =
      surfaceY +
      Math.sin(u * Math.PI * 2.0 + wavePhase1) * waveAmp +
      Math.cos(u * Math.PI * 3.5 - wavePhase2) * (waveAmp * 0.25);
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(inRight, inBot);
  ctx.closePath();
  const liqGrad = ctx.createLinearGradient(cx, surfaceY - waveAmp, cx, inBot);
  liqGrad.addColorStop(0, "#84F542");
  liqGrad.addColorStop(0.35, "#10D98B");
  liqGrad.addColorStop(1, "#047857");
  ctx.fillStyle = liqGrad;
  ctx.fill();

  // Crisp meniscus highlight
  ctx.beginPath();
  for (let s = 0; s <= steps; s++) {
    const u = s / steps;
    const wx = inLeft + u * inW;
    const wy =
      surfaceY +
      Math.sin(u * Math.PI * 2.0 + wavePhase1) * waveAmp +
      Math.cos(u * Math.PI * 3.5 - wavePhase2) * (waveAmp * 0.25);
    if (s === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.lineWidth = Math.max(1.5, minSide * 0.003);
  ctx.strokeStyle = "#D9F99D";
  ctx.stroke();

  // Rising Bubbles in Outer Left & Right Fluid Lanes ONLY
  const bubbles = [
    { lane: -0.086, speed: 3, phase: 0.08, r: 0.0052 },
    { lane: -0.076, speed: 4, phase: 0.56, r: 0.0038 },
    { lane: 0.086, speed: 3, phase: 0.34, r: 0.0050 },
    { lane: 0.077, speed: 4, phase: 0.78, r: 0.0036 },
  ];

  const bubbleBottom = inBot - minSide * 0.015;
  const bubbleTopLimit = surfaceY + minSide * 0.018;
  const travelSpan = bubbleBottom - bubbleTopLimit;

  if (travelSpan > minSide * 0.025) {
    for (let i = 0; i < bubbles.length; i++) {
      const b = bubbles[i];
      const prog = (cycleNorm * b.speed + b.phase) % 1;
      const by = bubbleBottom - prog * travelSpan;
      const bx = cx + b.lane * minSide + Math.sin(prog * Math.PI * 2) * (minSide * 0.004);
      const bAlpha = Math.sin(Math.PI * prog) * 0.75;

      if (bAlpha > 0.04) {
        ctx.beginPath();
        ctx.arc(bx, by, minSide * b.r, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(236, 253, 245, " + bAlpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // Central Botanical Leaf Core
  const rootY = inBot - minSide * 0.026;
  const maxStemH = inH * 0.66;
  const stemTopY = rootY - maxStemH * stemGrow;
  const stemBorderW = minSide * 0.011;
  const stemCoreW = minSide * 0.0048;

  ctx.beginPath();
  ctx.moveTo(cx, rootY);
  ctx.lineTo(cx, stemTopY);
  ctx.lineCap = "round";
  ctx.lineWidth = stemBorderW;
  ctx.strokeStyle = "#062024";
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(cx, rootY);
  ctx.lineTo(cx, stemTopY);
  ctx.lineCap = "round";
  ctx.lineWidth = stemCoreW;
  ctx.strokeStyle = "#ECFDF5";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, rootY, minSide * 0.013, 0, Math.PI * 2);
  ctx.fillStyle = "#062024";
  ctx.fill();
  ctx.beginPath();
  ctx.arc(cx, rootY, minSide * 0.0085, 0, Math.PI * 2);
  ctx.fillStyle = "#A7F3D0";
  ctx.fill();

  const leafBorderW = minSide * 0.0075;
  const lowerY = rootY - (rootY - stemTopY) * 0.42;
  const upperY = rootY - (rootY - stemTopY) * 0.74;

  drawLeaf(
    cx - minSide * 0.002,
    lowerY,
    -Math.PI * 0.76 + leafSway,
    minSide * 0.062,
    0.34,
    lowerLeavesOpen,
    "#D9F99D",
    "#84F542",
    "#062024",
    leafBorderW
  );
  drawLeaf(
    cx + minSide * 0.002,
    lowerY,
    -Math.PI * 0.24 - leafSway,
    minSide * 0.062,
    0.34,
    lowerLeavesOpen,
    "#84F542",
    "#D9F99D",
    "#062024",
    leafBorderW
  );

  drawLeaf(
    cx - minSide * 0.002,
    upperY,
    -Math.PI * 0.73 - leafSway * 0.8,
    minSide * 0.050,
    0.34,
    upperLeavesOpen,
    "#D9F99D",
    "#34D399",
    "#062024",
    leafBorderW
  );
  drawLeaf(
    cx + minSide * 0.002,
    upperY,
    -Math.PI * 0.27 + leafSway * 0.8,
    minSide * 0.050,
    0.34,
    upperLeavesOpen,
    "#34D399",
    "#D9F99D",
    "#062024",
    leafBorderW
  );

  drawLeaf(
    cx,
    stemTopY + minSide * 0.002,
    -Math.PI * 0.5 + leafSway * 0.5,
    minSide * 0.044,
    0.36,
    crownLeafOpen,
    "#ECFDF5",
    "#84F542",
    "#062024",
    leafBorderW
  );

  // Subtle flat-vector glass specular highlight
  const specX = inLeft + minSide * 0.015;
  ctx.beginPath();
  ctx.moveTo(specX, inTop + minSide * 0.032);
  ctx.lineTo(specX, inBot - minSide * 0.045);
  ctx.lineCap = "round";
  ctx.lineWidth = minSide * 0.007;
  ctx.strokeStyle = "rgba(216, 255, 240, 0.22)";
  ctx.stroke();

  ctx.restore();

  // Crisp Battery Shell Border
  roundedRectPath(batLeft, batTop, batW, batH, batR);
  ctx.lineWidth = minSide * 0.008;
  ctx.strokeStyle = "#D8FFF0";
  ctx.stroke();
}
